window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_053"]={"n":"陈琏","dyn":"明","poems":[{"t":"多景楼","f":"五言律诗","c":["独倚阑干久，凉风满客衣。","树从京口断，山到海门稀。","雁影横秋色，蝉声送夕晖。","芜城才咫尺，楼堞望中微。"]},{"t":"驺虞诗","f":"古风","c":["圣教敷，遍寰区。","吁驺虞，见雒墟。","步履啖食何尔殊，生来自有仁义俱。","目盱盱，烁明珠。","玉作爪，雪为肤。","黑文班班备五采，形质自异凡于菟。","进皇都，叶贞符，世所无。","不比九真犀，不比渥洼驹。","祥麟与瑞凤，太史堪并书。","小臣作诗颂圣德，千秋万载昭皇图。"]},{"t":"麒麟诗","f":"古风","c":["至和储精，麒麟降生。","麇身牛尾，马蹄龙睛。","身备五采，绚烂晶荧。","性尤仁厚，瑞图可徵。","不远万里，来自南溟。","祥云瑞霭，光绚阙廷。","出入金门，迩乎龙軿。","群臣聚观，喜跃弗胜。","惟昔太祖，天命是膺。","皇风以穆，皇道以贞。","九夷八蛮，莫不来庭。","冲和氤氲，屡致嘉祯。","皇帝嗣位，天下以宁。","仁被动植，泽及含灵。","祯祥沓至，以昭太平。","祥麟之来，适际文明。","惟帝之圣，贞符是承。","有濯厥声，耀于万龄。"]},{"t":"狮子诗","f":"五言古诗","c":["圣皇御寰宇，声教周八极。","四夷慕仁化，入贡来重译。","珍禽与奇兽，所见迈于昔。","维时有神兽，其类同白泽。","气禀金精刚，名为群毛特。","绀眸悬日星，碧爪利锋镝。","雄诡挺殊姿，杰异见材力。","或时恣哮吼，百盖俱辟易。","一朝从西来，万里度沙碛。","百兽同率舞，无乃感圣德。","昔汉章和间，入贡自安息。","有唐贞观中，又复来西极。","是后寂无闻，奇玩喜今日。","欢声腾厚地，嘉叹动百辟。","小臣际时康，歌颂乃其职。","抽毫纪嘉瑞，千古光史册。"]},{"t":"湘灵操","f":"楚辞体","c":["玉貌兮婵娟，联翠袖兮风前。","望翠华兮已远，临湘水兮凄然。","凤不来兮岁阑，秋气肃兮空山。","倚枫江兮惆怅，泪染竹兮斑斑。"]},{"t":"箕山操","f":"楚辞体","c":["箕山兮幽幽，箕水兮浟浟。","山可耕兮而樵，水可饮兮而游。","我于世兮无求，彼何故兮遗我以忧。"]},{"t":"风木操","f":"楚辞体","c":["维风之飂飂兮，而树之相樛兮，念夫亲之悠悠兮。","维风之淅淅兮。","而树之槭槭兮，念夫亲之不可复得兮。","树之有风，犹可止兮。","吾之念亲，终无已兮。"]},{"t":"招鹤辞","f":"楚辞体","c":["嗟尔鹤兮，来自芝田。","玄裳缟衣兮，羽仪何鲜。","戛然长鸣兮，其音清圆。","翩然起舞兮，其影蹁跹。","与尔相处兮，阅有岁年。","何一夕羽化兮，竟去不还。","非赴瑶池之会兮，定随蓬岛之仙。","惟轩有梧兮竹猗猗，尔其来归兮安所栖。","惟轩有泉兮秀三芝，尔其来归兮无渴饥。","我弹瑶琴兮按金徽，我吹玉箫兮叶埙篪，尔其来归兮以终幽期。","无奋迅兮高飞，使我心兮劳思。"]},{"t":"云林雅兴辞为训导王中赋","f":"楚辞体","c":["白云兮央央，群山兮苍苍。","云之间兮乔木，山之阳兮草堂。","中有美人兮貌清且扬，胸中粲粲兮五色文章。","纫幽兰兮为佩，制芙蓉兮为裳。","玄猿吟兮春云暝，白鹤怨兮秋夜长。","弹孤桐兮自适，思佳人兮难忘。","安得跨飞鸾兮容与，栖云山兮尚羊。"]},{"t":"幽谷辞为范孟祯先生赋","f":"楚辞体","c":["谷之深兮窈窕，谷之幽兮山麓。","气濛溶兮白云，阴蔽亏兮嘉木。","芝烨烨兮可餐，泉泠泠兮可掬。","供啸傲兮烟霞，同游嬉兮麋鹿。","谅劳生兮焉休，蹈前修兮遗躅。","嗟岁月兮几何，聊盘桓兮幽独。"]},{"t":"天马歌","f":"古风","c":["汗血神驹不世出，一旦生下月氏窟。","凤臆龙鬐首渴乌，身带虎文异筋骨。","朝刷昆崙，暮秣西极。","电迈飙驰，不可慌惚。","仰天长鸣，万骑辟易。","忆昔元封盛治时，长驱万里来京师。","天子纵观心独喜，荐诸宗庙形歌诗。","翠云为鞁七宝鞍，置之天驷十二闲。","乘舆亲临至甘泉，曾骖玉辂鸣和鸾。","君不见汉家凋弊由天马，无限生灵膏草野。","万古千秋恨未消，至今鬼哭宛城下。"]},{"t":"白纻词二首 其一","f":"七言律诗","c":["胭脂半湿红玉春，远山不扫娇娥颦。","歌声飘飘绕梁尘，玳瑁筵前月色新，管弦相和哀思匀。","子夜沉沉更漏促，绛蜡摇光照银屋，馆娃宫人听未足。"]},{"t":"白纻词二首 其二","f":"古风","c":["舞白凫，歌白纻，纤腰皓齿东邻女。","清声袅云情缕缕，郢中白雪何足数。","凉风萧萧雁南翔，玉颜满堂乐未央，此舞此歌那可忘。"]},{"t":"乌栖曲","f":"七言绝句","c":["井梧叶落惊乌起，深院沉沉烛花紫。","门前月色冷如霜，忆郎不来空断肠。"]},{"t":"阳春歌","f":"五言律诗","c":["冰帘捲秋水，宝鸭腾烟缕。","幽思满银筝，彩弦愁独理。","不见知心人，无言泪如雨。","一曲陌上歌，谁是采桑女。"]},{"t":"十二月词效李长吉体 其一 正月","f":"七言律诗","c":["东郊美人迎新春，春光茫茫烟满津。","江头水生杨柳新，色染鹅黄犹未匀。","和风丽日催兰蕙，淑气融融塞天地。","无心去理阳春曲，闲把修娥斫双绿。"]},{"t":"十二月词效李长吉体 其二 二月","f":"古风","c":["采桑南陌头，陌头花开风力柔。","吴媮向人扬清讴，花底怨春胡燕愁。","社雨初晴路如洗，轧轧车声转流水。","罗裙翠袖香风起，芳草萋萋暮烟紫。"]},{"t":"十二月词效李长吉体 其三 三月","f":"七言古诗","c":["七星挂城宫漏残，别院悬帘秋水寒。","琐窗梦断莺声老，满地落红闲不扫。","脉脉芳心向谁道，蝴蝶飞来满芳草。","光风淡淡春云热，江上菖蒲想堪结。","春住春归总不知，愁看十里杨花雪。"]},{"t":"十二月词效李长吉体 其四 四月","f":"七言古诗","c":["平塘水流声溘溘，波凝鸭绿琉璃滑。","横船醉眠白昼长，浦口梅风歌扇香。","老红堕地花已稀，幽篁娟娟弄粉姿，美人怅望别离时。"]},{"t":"十二月词效李长吉体 其五 五月","f":"五言律诗","c":["湘帘捲秋水，玉簟凉冰肌。","鹍弦诉幽怨，凤笙吹参差。","杯浮甘露浆，井汲铅华水。","歌罢綵云空，南薰四筵起。"]},{"t":"十二月词效李长吉体 其六 六月","f":"古风","c":["赤帝来，火龙出，下土炎炎畏红日。","翠华摇摇宴水晶，仙风泠泠透骨清，何须赤脚踏层冰。"]},{"t":"十二月词效李长吉体 其七 七月","f":"五言古诗","c":["星桥驾乌鹊，秋竹度秋萤。","舞衫嫩凉结，纨扇幽恨并。","蘼芜花正发，衰兰色已零。","霄寒紫罗荐，露湿芙蓉屏。","孀妾耿忘寐，此心常独惺。"]},{"t":"十二月词效李长吉体 其八 八月","f":"五言律诗","c":["桂影月中现，桂香天外飘。","玉佩湘娥解，锦瑟佳人调。","灯青兰膏煖，灰寒沉水消。","城鸦啼粉堞，河落曙萧萧。"]},{"t":"十二月词效李长吉体 其九 九月","f":"七言古诗","c":["井梧叶落银床冷，月下孤鸾吊寒影。","院宇沉沉清似水，闪闪光摇烛花紫。","长歌白纻敲悬珰，绿香绣幕愁夜长。"]},{"t":"十二月词效李长吉体 其十 十月","f":"七言古诗","c":["鸳鸯瓦冷霜华薄，剪剪轻寒透罗幕。","银缸吐花凝幽光，击钟挝鼓饮华堂。","万籁沉沉夜方永，玉兔无声堕寒影，酒阑人散笙歌静。"]},{"t":"十二月词效李长吉体 其十一 十一月","f":"七言古诗","c":["雪花六出碎琼芳，九成宫阙参差光。","一声白纻樽前起，琵琶枨枨寒玉指。","火井温泉何处寻，氍毹醉卧雕房深。"]},{"t":"十二月词效李长吉体 其十二 十二月","f":"七言绝句","c":["湘筠冻折琅玕玉，冷逼青楼起寒粟。","依微和气酒中回，龟甲屏风照银烛。"]},{"t":"闰月","f":"古风","c":["阳生玉琯葭灰浮，二十四气推步周。","颁重光，歌重轮，气朔不差岁始匀。","谁能更缓羲和辔，愿祝吾皇千万岁。"]},{"t":"朱鹭","f":"古风","c":["朱鹭来，集天池。","丹为裳，砂为衣。","朱鹭来，色光华。","耀晨曦，映晴霞。","朱鹭来，自丹丘。","繄赤凤，可同游。","朱鹭来，际时雍。","神筴演，庆无穷。","朱鹭来，彰有德。","和气充，百福集。","朱鹭来，协嘉祥。","登瑞图，煊有光。"]},{"t":"艾如张","f":"楚辞体","c":["维时讲春蒐，徒旅集崇阿。","有鸟萃方丛，榛楛一何多。","芜秽既剪伐，张机设虞罗。","群鸟忽高举，罗兮奈尔何。"]},{"t":"芳树篇","f":"五言古诗","c":["中庭蔼嘉树，清影荫兰池。","密叶惠风拂，灵根华泉滋。","奇葩纷旖旎，艳质复葳蕤。","佳人间幽室，对此惜容辉。","含情理哀弦，弹作阳春辞。","清音自激越，此意谁能知。","恒恐秋节至，严霜悴芳枝。","流光驹过隙，欢乐当及时。"]},{"t":"巫山高","f":"古风","c":["巫山高，高刺天，峰峦十二开青莲。","阳台神女竟何在，朝云暮雨犹依然。","宋玉微词徒自诧，襄王荒怪益堪怜。","山下遗宫总芜没，空馀猿狖啸苍烟。"]},{"t":"铜雀台","f":"五言古诗","c":["铜雀高峨峨，百尺淩云烟。","台中贮群妓，颜色如花妍。","霓旌不复来，已筑西陵土。","白日闭泉扃，何由见歌舞。","穗帏闲夜月，玉座空秋风。","脯糒方荐罢，瞻望意无穷。"]},{"t":"铜雀妓","f":"五言绝句","c":["西陵漳河上，松柏郁苍苍。","穗帏歌舞罢，含泪忆君王。"]},{"t":"晓仙谣","f":"七言古诗","c":["金鸡初号天未晓，绮阁沉沉漏声杳。","月华淡白涵春风，窗外碧桐青凤小。","蕊珠仙子素霓裳，腰间玉玦双明珰。","曜灵犹未启初景，飘飘欲得云间翔。","琅函夙授长生箓，服气餐霞胜辟谷。","青鸾有信喜相邀，瑶池早晚蟠桃熟。"]},{"t":"春愁曲","f":"七言律诗","c":["罗帏绣幕东风冷，金鸭香消春昼永。","睡起含情娇翠颦，宝簪坠鬓愁慵整。","沙苑芳郊草似茵，马蹄何处逐流尘。","恨紫怨红情脉脉，落花飞絮正纷纷。"]},{"t":"少年乐","f":"古风","c":["五花马，狐白裘，出门宾从如云稠。","二十长游醉乡里，双眉不识人间愁。","玳筵绮馔纷罗列，玉斝浮香酒微热。","舞袖轻回杨柳风，歌喉缓啭桃花月。","弹丝吹竹乐正浓，床头不惜黄金空。","世间万事何足虑，祇愁双鬓飞秋蓬。"]},{"t":"洛阳道","f":"古风","c":["洛阳道，平不颇，香车宝马纷来过。","落花飞红依度幰，垂柳拂地随鸣珂。","只言百岁事行乐，岂知掘地飞双鹅。","金谷繁华等春梦，道傍荆棘埋铜驼。"]},{"t":"长安道","f":"古风","c":["长安道，平如砥，道傍甲第连云起。","五侯七贵竞豪奢，管弦嘈嘈聒人耳。","从来盛衰当有时，富贵百年安可期。","一朝宾客如云散，门外草生车马稀。"]},{"t":"陇头水","f":"五言古诗","c":["驱车上陇阪，山高谷逶迤。","流水日夜鸣，幽咽不胜悲。","秦川遥在望，离思正依依。"]},{"t":"关山月","f":"七言律诗","c":["冰轮流辉天宇宽，长风吹度玉门关。","玉关无云秋万里，月色满空凉似水。","远客思归睡不成，况复边头来雁声。","楼中美人当此夕，坐对清辉应叹息。"]},{"t":"鸿门宴","f":"七言古诗","c":["嬴秦蚕食六国空，刘项崛起谁雌雄。","芒砀已见天子气，楚氛犹袭咸阳宫。","鸿门何人出秘计，天意先已酣重瞳。","剑光辉霍射人目，座间飒飒生寒风。","帐前玉斗一声碎，风云已去随真龙。","汉基四百由此造，当时独数留侯功。"]},{"t":"将进酒","f":"古风","c":["蝉衫麟带袭琼芳，雕筵绮席生辉光。","主人敬客捧瑶觞，紫檀夜压松花香。","人间真趣无如酒，再拜客前千万寿。","纵饶黄金恒满籯，何如一杯长在手。","鸬鹚杓，玻璃罂。","但愿千日醉，不愿一时醒。","君不见王无功，一生长在尊酒中。","又不见晋刘伶，醉乡深处度平生。","前代英雄纷莫数，二子之名传万古。"]},{"t":"雉子斑","f":"七言律诗","c":["棠梨花开春昼长，麦苗雨过青茫茫。","一双燕子下山梁，雌雄相逐何尔忙。","斑斑五采粲成章，麦陇虽深难久藏。","上林日煖千花香，何不高飞随凤凰。"]},{"t":"杨白花","f":"古风","c":["杨白花，随风飞去落谁家。","美人沉思抱幽怨，连臂踏歌情恋恋。","江南江北春茫茫，何不仍飞归洛阳。"]},{"t":"野田黄雀行","f":"七言绝句","c":["稻熟平田秋已暮，黄雀飞来日无数。","可怜齐啄稻为空，鹰隼不来愁老翁。"]},{"t":"鸡鸣曲","f":"七言律诗","c":["明河欲没天将晨，鸡鸣咿喔惊四邻。","美人锦帐睡正浓，壮士感激心忡忡。","百年三万六千日，日日鸡鸣催日出。","龙泉起舞歌慨慷，谁识此声能断肠。"]},{"t":"驱车出东门","f":"五言古诗","c":["驱车出东门，露华满衰草。","天高鸿雁稀，木落秋风早。","佳人期不至，远隔关河道。","日暮幽思多，芳尊共谁倒。","岁月去如流，人生几回老。","驱车出东门，聊尔散隐忧。","赪霞烧广泽，红叶明素秋。","风霜岁云暮，禾黍日已稠。","野老笑相语，亹亹情不休。","幸生圣明世，谁能学幽求。"]},{"t":"步虚词四首 其一","f":"五言古诗","c":["紫虬何婉婉，驾我升云輧。","绛露湿宝盖，祥云拥霓旌。","谁谓天路遥，倏歘淩太清。","真童远相迓，导引趋天庭。","稽首虚皇前，思竭蝼蚁诚。","愿祈圣人寿，永享亿万龄。"]},{"t":"步虚词四首 其二","f":"五言古诗","c":["榑桑启丹景，祥光烛璇霄。","肃驾朝紫皇，大罗望迢迢。","琼林郁葱茜，天香随处飘。","我喜跻阳原，中心乐逍遥。","自非挺金骨，群真宁见招。","但尔葆贞气，无劳问松乔。"]},{"t":"步虚词四首 其三","f":"五言古诗","c":["高升紫极上，独步金阙前。","琼佩响灵风，羽服凝紫烟。","瑶池锡嘉宴，济济来群仙。","坐我八景舆，授我鸿宝篇。","云璈声方歇，广乐张钧天。","良期无终极，俯仰成千年。"]},{"t":"步虚词四首 其四","f":"五言古诗","c":["肆觐白玉京，高登明真台。","遥望三素云，飘飘绕蓬莱。","仙山郁嵯峨，蟠桃几回开。","且喜王道融，祥风净氛埃。","飙轮涉寥廓，百灵俨相随。","不觉云路遥，鸾凤共徘徊。"]},{"t":"读史有感八首 其一","f":"五言古诗","c":["周纲日陵替，七雄互并吞。","嬴秦逞诈力，侧足窥中原。","纷纷纵横士，矜志道逾昏。","徒嗜世禄富，岂知王室尊。","伟哉鲁连子，千载无间言。"]},{"t":"读史有感八首 其二","f":"五言古诗","c":["刘项本勍敌，龙虎自吞噬。","宽仁与残暴，成败亦自异。","项疑范增谏，刘悟董公说。","乌江既羞渡，咸阳合称帝。","遗臭与流芳，亦各垂万世。"]},{"t":"读史有感八首 其三","f":"五言古诗","c":["巍巍汉高皇，应运肇丕基。","相承六七叶，大业忽中衰。","新莽逞奸谋，暂将炎鼎移。","南阳真人出，群雄翕相随。","冰合滹沱河，天意已可知。","况有赤伏符，暗与休运期。","云台有遗烈，千载起予思。"]},{"t":"读史有感八首 其四","f":"五言古诗","c":["曹瞒瞰中原，孙郎奋江东。","英英帝室胄，偏都巴蜀中。","一心复旧物，三顾起卧龙。","大业张垂成，天运忽告终。","将星落前军，炎灰散寒风。","三分从此始，千古恨莫穷。"]},{"t":"读史有感八首 其五","f":"五言古诗","c":["五马渡江左，国步日孔棘。","亹亹尚清谈，于世竟奚益。","新亭忧堕泪，别墅喜折屐。","若能贾馀勇，中原可复得。","奈何失此机，上下尚姑息。","坐视犬戎争，腥膻污中域。","伟哉祖与卞，义气徒感激。","大厦柱难支，中流楫徒击。"]},{"t":"读史有感八首 其六","f":"五言古诗","c":["六朝迭更运，俛仰三百年。","淳风变浇漓，中华污腥膻。","文章喜骈丽，诗歌竞清妍。","上下洵宴安，酒色日流连。","至今后庭花，闻之尚凄然。"]},{"t":"读史有感八首 其七","f":"五言律诗","c":["晋阳肇唐基，君臣总英哲。","学士登瀛洲，庙堂居稷契。","宝历甫三传，阴祸日连结。","倘非张狄公，大业在兹绝。"]},{"t":"读史有感八首 其八","f":"五言古诗","c":["皇风久不宣，王纲日陵替。","相传仅五姓，维时称叔季。","忠良尽沉郁，礼乐亦荒废。","悠悠六十年，白日似昏翳。","懿哉欧阳公，作史寓深意。"]},{"t":"读汉武本纪","f":"五言古诗","c":["汉武英明主，善操威福权。","思复七世雠，锐志开北边。","骏马来西极，武功耀三边。","中年惑方士，入海求神仙。","金丹既罔效，何物堪延年。","晚岁发深省，用心师圣贤。","六经赖表章，道如日当天。","我读轮台诏，不愧秦誓篇。"]},{"t":"题对奕图","f":"五言古诗","c":["宦情淡如水，佛性了难觉。","饱食无所事，手谈有真乐。","苏黄号劲敌，往往见奇着。","机深势莫测，意快子先落。","安危付所之，胜负焉用角。","老师捏槃坐，神思自冲漠。","一局看未终，千载宛如昨。"]},{"t":"寄义宁教谕李仲脩","f":"五言古诗","c":["高斋坐岑寂，怀贤思难禁。","薰风从南来，泠然吹我襟。","红芳倏已歇，绿树看成阴。","感此节序乖，何由论夙心。","有琴不成操，有酒谁共斟。","幽期旷难卜，西望空长吟。"]},{"t":"寄尹伯宏兼柬陈克杰四首 其一","f":"五言古诗","c":["别君岁已久，忆君梦亦频。","昨看黄叶落，又见芳草新。","韶光倏焉迈，感此独怆神。","旧欢不可追，嘉会良无因。","相思一长啸，月满湘南春。"]},{"t":"寄尹伯宏兼柬陈克杰四首 其二","f":"五言律诗","c":["悠悠念亲爱，惨惨郁中素。","迢迢阻山岳，漠漠隔烟树。","小山谁见招，沧洲动归趣。","人生等浮萍，聚散安得屡。"]},{"t":"寄尹伯宏兼柬陈克杰四首 其三","f":"五言古诗","c":["斋居夜岑寂，万籁声已沉。","怀人耿不寐，幽思盈素襟。","此情孰能写，试理膝上琴。","谁知一曲音，遽有千里心。","何当归去来，同和山中吟。"]},{"t":"寄尹伯宏兼柬陈克杰四首 其四","f":"五言律诗","c":["漓水冬不波，桂林寒有雪。","江空岁华宴，客子念离别。","心随归雁远，兴逐梅花发。","独忆山中人，长年守贞洁。"]},{"t":"夜宿马王阁都纲胜义天精舍","f":"五言律诗","c":["石壁风飕飕，山房人寂寂。","清心契神境，万虑若冰释。","揽衣起徘徊，自扫松下石。","忽闻孤鹤声，满庭秋月白。"]},{"t":"饯义宁知县利原厚","f":"五言古诗","c":["人生重离别，君去何匆匆。","携手上河梁，绮筵散香风。","波荡鸭头绿，花开腥血红。","诗题青玉案，酒泛玻璃钟。","莫辞花下醉，明日各西东。"]},{"t":"送杨秋江归羊城","f":"五言古诗","c":["冥鸿响瑶渚，秋声满江干。","严霜悴百草，萧条风景寒。","人生在知己，远别良独难。","岂无绿绮琴，不忍向君弹。","岂无白纻歌，歌来转辛酸。","聊持一尊酒，暂结半日欢。","酒醒愁复在，何如赠琅玕。","琅玕世所重，分刻两佩环。","一作双蟠螭，一作双回鸾。","上可献天府，下可慰慈颜。","愿君永佩之，佩之当佩兰。"]},{"t":"纳凉逍遥楼","f":"五言古诗","c":["书舍大如斗，烦暑苦郁蒸。","危阑俯长江，晚来试一凭。","披襟待明月，坐爱风泠泠。","逍遥遗俗虑，物我两忘形。","只此足清赏，何须踏层冰。"]},{"t":"游韶音洞二首 其一","f":"五言古诗","c":["重华去云久，千载有遗踪。","韶音已寂寥，石洞犹穹窿。","秋风吹古桂，朝阳老孤桐。","蝉吟白日静，凤去彩云空。","我来重怀古，转觉心冲冲。"]},{"t":"游韶音洞二首 其二","f":"五言古诗","c":["平生爱明胜，寻幽起辞远。","折花度瑶涧，扪萝陟层巘。","目穷数百里，身历千万转。","我心本无碍，浮云共舒卷。","留欢竟忘返，不觉归路晚。"]},{"t":"饮射观德亭","f":"五言古诗","c":["秋日天气佳，凉飔满林扃。","宇宙绝纤翳，万里同清明。","群贤协嘉会，饮射集斯亭。","弯弓似满月，飞矢如流星。","若能正一己，胡忧失诸鴊。","缅怀三代时，斯礼讲素精。","大唐贞观初，胜事亦可徵。","后人宰钧衡，因以仆射名。","吾侪生盛世，况值文运兴。","古礼在究极，乐事良难并。","一有不中者，行当罚巨觥。"]},{"t":"雪月轩为千户萧世英赋","f":"五言古诗","c":["严冬风物佳，宵永寒风肃。","雪花大于掌，月色明如烛。","高轩喜虚敞，晴光夺人目。","万瓦铺琼瑶，空阶粲冰玉。","孤桐声何清，老鹤梦初熟。","逸兴满冲襟，长歌泻醽醁。"]},{"t":"游南薰亭","f":"五言古诗","c":["桂林名胜地，台观迹多陈。","空馀南薰亭，屹立漓水濆。","使君喜登临，从游有嘉宾。","拂石坐紫苔，援琴鼓南薰。","神畅情所感，理契意爰臻。","忽兹纵遐瞩，跻攀极嶙峋。","下瞰皇泽湾，流水碧沄沄。","石洞深窈窕，清虚绝垢氛。","昔贤有遗刻，半杂苔藓纹。","江山宛如故，韶音谁复闻。","登临稍毕景，感慨怀古人。","早晚听履声，行当近星辰。"]},{"t":"登刘仙岩","f":"五言古诗","c":["清飙惊流尘，晴旭严芳甸。","冠盖驻岩阿，从游总文彦。","仙家碧云中，丹光旧曾现。","鹤笙今寥寥，岁月疾于电。","亭台久荒芜，草木郁葱茜。","古碑横道隅，苔藓绿将遍。","跻攀出林杪，兴至辄忘倦。","八桂多好山，迤逦青对面。","目断三素云，蓬莱几人见。"]},{"t":"游七星岩","f":"五言古诗","c":["五岭炎蒸地，宜人惟桂林。","江流绿罗带，山列紫琼簪。","矧兹星岩胜，近在漓水浔。","松桧自萧瑟，石洞生幽阴。","使君天上来，览胜思登临。","冠盖集群彦，迤逦度高岑。","使节驻玄关，尽日穷幽寻。","稍已骋遐目，遂兹舒郁襟。","乾坤正纳纳，岁月去骎骎。","行乐当及时，有酒宜共斟。","俯仰百年内，何人知此心。"]},{"t":"拟古十九首 其一","f":"五言古诗","c":["亭亭峄山桐，枝干何尔奇。","托根喜得所，况承雨露滋。","材良不自弃，偶为匠石知。","制为绿绮琴，縆之以朱丝。","中含太古音，赏者世所希。","愿持献天子，为鼓南风诗。"]},{"t":"拟古十九首 其二","f":"五言古诗","c":["逍遥穹壤间，端居感流序。","岁月迭推迁，草木有荣悴。","劳生谅奚庸，顾为形役累。","富贵不可常，神仙亦难遇。","但愿身长健，有酒日日醉。"]},{"t":"拟古十九首 其三","f":"五言古诗","c":["春至淑气和，百卉媚芳姿。","此时二八妇，对景动忧思。","折花插蝉鬓，览镜画蛾眉。","暗惜桃李年，茕茕守空闺。","叹息复叹息，误身轻薄儿。"]},{"t":"拟古十九首 其四","f":"五言古诗","c":["猗兰满瑶砌，旦夕吐幽芳。","纫之以为佩，相爱恒不忘。","缅怀同心人，迢遥隔沅湘。","采采欲持赠，路远不得将。","徘徊风露下，抚心徒自伤。"]},{"t":"拟古十九首 其五","f":"五言古诗","c":["世道良悠悠，时序还草草。","凉风凄以寒，庭树日以槁。","人非金石固，容华岂长好。","读书期致君，立勋苦不早。","耿耿一寸丹，坚贞期自保。"]},{"t":"拟古十九首 其六","f":"五言古诗","c":["驰车鲜安旌，风林无定枝。","自愧云萍踪，岁月久暌违。","念我亲与友，各在天一涯。","音容两契阔，悲欢何由知。","倦鸟恋旧林，游鱼思故池。","忧来翻百端，耿耿当告谁。"]},{"t":"拟古十九首 其七","f":"五言古诗","c":["猗猗云间竹，直干参天长。","卑枝集繁露，劲节饱严霜。","频年不结实，彩凤徒翱翔。","一遇伶伦顾，用之中笙簧。","持以献清庙，淳音协宫商。"]},{"t":"拟古十九首 其八","f":"五言古诗","c":["明月何皎皎，流辉照我床。","起来弹素琴，音韵振琳琅。","忽忆平生友，别来似参商。","此意向谁诉，幽怀徒自伤。","安得如溟鸿，与之共翱翔。"]},{"t":"拟古十九首 其九","f":"五言古诗","c":["粲粲五色丝，织成云锦章。","深闺亲剪制，为君作衣裳。","时时幸披拂，佩服媚容光。","一朝忽弃置，兰麝徒自芳。","人情喜怜新，使妾空自伤。"]},{"t":"拟古十九首 其十","f":"五言古诗","c":["丹山有凤凰，身备五采文。","饮啄异凡鸟，不入鸡鹜群。","和鸣在朝阳，高举入青云。","一旦览德辉，来仪际昌辰。","诗书方见重，便为人所珍。"]},{"t":"拟古十九首 其十一","f":"五言古诗","c":["倚剑登高台，流盻青云端。","天地自高厚，节序如循环。","山川空历历，岁月去不还。","古人有遗迹，荒凉莱草间。","临风谩吊古，恻怆空长叹。"]},{"t":"拟古十九首 其十二","f":"五言律诗","c":["美人惜良夜，开宴近琼林。","达曙乐未已，清歌荡人心。","谁怜东邻女，轧轧弄机杼。","停梭忆远人，无言泪如雨。"]},{"t":"拟古十九首 其十三","f":"五言古诗","c":["永夕秋风至，长空度征雁。","徘徊步前墀，顾影空自叹。","凉露沾衣裳，明月转银汉。","佳人期未来，又觉岁华宴。","制得云锦书，迢迢托飞翰。"]},{"t":"拟古十九首 其十四","f":"五言律诗","c":["煌煌明月珠，夜夜吐清辉。","自从遇越客，美价重当时。","一朝混鱼目，按剑亦自宜。","奇宝世恒有，所贵识者希。"]},{"t":"拟古十九首 其十五","f":"五言古诗","c":["京雒繁华地，甲第溢通衢。","南邻击钟鼓，北里吹笙竽。","被服重纨绮，宴乐皆名姝。","豪气迈五陵，英声溢八区。","常恐光阴速，不得穷欢娱。","只言固恩宠，岂悟有荣枯。","却笑扬子云，独守太玄书。"]},{"t":"拟古十九首 其十六","f":"五言古诗","c":["人生百年内，少壮能几何。","欢乐常恨少，暌离恒苦多。","中宵揽衣起，桂影自婆娑。","仰视牛女星，相望隔银河。","昔人秉烛游，岁月恐蹉跎。","沉思耿不寐，太息继以歌。"]},{"t":"拟古十九首 其十七","f":"五言古诗","c":["天道亦何言，寒暑自推移。","福善与祸淫，斯理恒昭而。","嗟嗟誇毗子，矜智竟奚为。","虽云适时好，还为君子嗤。","居易以俟命，圣人岂吾欺。"]},{"t":"拟古十九首 其十八","f":"五言古诗","c":["穷巷屏人迹，不为尘俗混。","粗衣与粝食，寡欲中鲜吝。","徼福非所希，安贫乃吾分。","典籍时讨论，圣哲有明训。","兀兀坐蓬门，默默观大运。"]},{"t":"拟古十九首 其十九","f":"五言古诗","c":["我闻古仙人，皓齿赪玉颜。","餐霞饮沆瀣，来往三神山。","每欲从之游，逸驾邈难攀。","思之令人老，矧值芳岁阑。","颓龄倘可驻，何惜炼金丹。"]},{"t":"中秋对月","f":"五言古诗","c":["入夕雨初霁，浮云净如扫。","华月忽东升，寒光满晴昊。","天香落丹桂，珠露缀瑶草。","开筵近前墀，贪爱月色好。","陶然欢笑中，不惜玉尊倒。","举杯问姮娥，人生几回老。"]},{"t":"送都给事中徐公琦升广东右布政使","f":"五言古诗","c":["迢迢五羊城，旧本百越地。","堂堂启雄藩，岭海一都会。","朝廷重方岳，选拜定勋贵。","维公闽之彦，素有廊庙器。","日侍禁闼中，直言无少避。","忠诚格宸衷，宠眷特殊异。","一朝奉明诏，出守方伯位。","足展经纶才，不负平昔志。","顾予忝朝行，久矣慕高义。","侧闻沐新恩，自觉喜忘寐。","伫看宣上德，惠泽洽南裔。"]},{"t":"斋居许州兴国寺是夜大雪","f":"五言古诗","c":["斋居息尘虑，禅房掩虚阒。","瑶琴静在几，银灯炯当席。","江空岁华宴，矧遇风雪夕。","琪花散寒光，玉树森素色。","疲氓思抚摩，中夜心恻恻。","愿祈岁年丰，幸兹睹三白。"]},{"t":"得舍弟琦在京师寄来书","f":"五言古诗","c":["我昨荷天宠，分符别京师。","一麾守名郡，素节恒自持。","家山别已久，骨肉重怀思。","迢迢川途远，荏苒尺书稀。","沉忧结衷曲，会晤良无期。","感此泽中雁，分飞竟何为。","予告应可待，同戏斑斓衣。"]},{"t":"春日郡斋有怀成均诸先生","f":"五言古诗","c":["春阳应候至，万虑遂枯荣。","烟消芳草积，雨过嘉苗生。","流莺何处来，睍睆闻新声。","同心间徽音，感此独凝情。","相望渺川岳，何时当合并。"]},{"t":"西湖即事","f":"五言古诗","c":["灵雨浥流尘，旭旦明芳甸。","乘兴出闉阇，行行恣游衍。","沿堤访古迹，临水列华宴。","蕙风泛羽觞，花露湿文砚。","景物岂予顾，所乐在群彦。"]},{"t":"八龙冢","f":"五言古诗","c":["荀氏好昆仲，当时称八龙。","慈明信无双，声誉何隆隆。","孝义萃一家，莫匪庆所钟。","史籍著遗烈，耿耿垂无穷。","城北有封竁，荆棘结蒙茏。","墓门闭白日，宰木号清风。","兹晨偶经此，转觉心冲冲。"]},{"t":"晁错墓","f":"五言古诗","c":["晁公颍川彦，文藻重当时。","风云际嘉会，夙受汉主知。","谠言人所难，敷奏竟弗疑。","才彻九重听，已堕奸人机。","哀哉东市冤，千古令人悲。","倘非董公说，孰能明是非。","城东有遗冢，宿草荒离离。","我来览遗址，感慨徒歔欷。","赖有忠名在，不随薤露晞。"]},{"t":"访李秋谷祠堂遗址","f":"五言古诗","c":["前代有名臣，晚节号秋谷。","声名隘寰宇，勋业重钧轴。","初年居许昌，别墅依水曲。","光风泛崇兰，苍雪洒修竹。","当时择名胜，此地擅幽独。","俯仰成百年，乐事随转烛。","故基长蒿莱，终日来樵牧。","我今重经过，恻怆访遗躅。","清风已寥寥，芳草几回绿。"]},{"t":"郡斋偶成","f":"五言古诗","c":["滁阳畿甸郡，俗美民复淳。","况逢文明世，教化聿以新。","我本樗散材，夙忝列朝绅。","一朝纡郡绂，实荷圣主恩。","编氓在抚摩，风俗在所惇。","才疏力复孱，恒恐愧古人。","念昔欧阳公，遗爱在滁民。","每怀踵芳躅，黾勉效忠勤。"]},{"t":"送吴寺丞二首 其一","f":"五言律诗","c":["滁阳启天厩，騋牝萃郊原。","神驹日蕃息，百万如云屯。","君今奏成绩，稽首朝至尊。","太史纪盛事，汉唐何足论。"]},{"t":"送吴寺丞二首 其二","f":"五言律诗","c":["晴旭丽芳甸，凉飔起修林。","纷纷集冠盖，歌吹激清音。","相逢暂容与，别意那能禁。","明发天上去，五云宫阙深。"]},{"t":"永乐四年秋丁适庙学修理完美喜而有赋","f":"五言古诗","c":["皇明重儒术，声教轶黄唐。","滁实畿甸郡，庙学启堂堂。","属兹修饰后，藻绘倍焜煌。","维时仲秋初，丁祀礼有常。","钟鼓宿在悬，佾舞俨成行。","牲醴既嘉旨，黍稷复馨香。","僚采严祀事，冠佩来跄跄。","匪侈仪物丰，所贵诚意将。","予时躬裸奠，虔虔靡或忘。","神灵谅昭假，锡福何穰穰。","仰惟天子圣，建极宣重光。","盛典重兴举，声烈冠百王。","愿祈亿万年，儒风振无疆。"]},{"t":"寄永州姜仲琏公子","f":"五言律诗","c":["琅琊消积雪，滁阳惊早春。","美人隔千里，离思集芳辰。","长吟还浩叹，嘉会良无因。","何当共携手，采兰湘水滨。"]},{"t":"赠朔州千户萧世英","f":"五言古诗","c":["君从雁门来，鞍马光陆离。","我喜觌颜色，不异璚树枝。","叙意把芳札，写心命朱丝。","契阔方及展，暌违复在兹。","别后慎自爱，远大以为期。"]},{"t":"兰蕙同芳为吴指挥赋","f":"五言古诗","c":["阴阳运玄化，万汇咸熙熙。","兰蕙发佳祥，晔晔见贞姿。","同根固云好，并秀一何奇。","光风转新绿，清露湛琼蕤。","含翘纷旖旎，懹馨竞华兹。","幽芳异群卉，夙受君子知。","造物寓深意，钟瑞表明时。"]},{"t":"沧浪渔隐为陈规训导赋","f":"五言古诗","c":["沧浪渺何许，乃在均之阳。","泠泠浸霞采，湛湛涵天光。","中有隐君子，渔钓日尚羊。","风吹紫兰佩，露湿芙蓉裳。","持竿弄明月，志不在鳣鲂。","时歌欸乃曲，苍茫烟水长。"]},{"t":"送凤阳府杨通判升河间知府","f":"五言古诗","c":["条风被原隰，春日欣晴明。","使君天上来，五马拥双旌。","相逢暂容与，握手话平生。","赠君瑶华篇，劝君白玉觥。","既醉复云别，绻缱难为情。","去去守名郡，珍重在斯行。"]},{"t":"宴集祝太仆西山暮景轩","f":"五言古诗","c":["人生贵适意，况乃遇佳辰。","盍簪情弥欢，对酒趣益真。","条风荡繁吹，艳曲歌阳春。","倏焉西山暮，金碧炫嶙峋。","高轩罢华宴，归骑蹴芳尘。"]},{"t":"游龙潭分韵得雁字","f":"五言古诗","c":["龙潭幽胜地，杰木倚霄汉。","楼阁郁嵯峨，金碧互璀粲。","维时夏初临，风清日方晏。","喜与文翰俦，嬉游恣吟玩。","折芳藉瑶席，洗盏俯寒涧。","泉鸣琴韵佳，鸟啭歌喉慢。","登临且尽欢，怀古谩兴叹。","记取重游期，长空度归雁。"]},{"t":"送潞州节判王尹实复任","f":"五言律诗","c":["邂逅南谯城，喜共论心素。","客意方绸缪，行色复匆遽。","琼液注芳尊，鸾笺赠新句。","去去重相思，太行渺烟树。"]},{"t":"环翠草堂为毕思诚赋二首 其一","f":"五言古诗","c":["金谷久荒寂，平泉亦丘墟。","孰知中林士，幽居恒宴如。","嘉树纷缭绕，翠色自扶疏。","好风时一来，清气满庭除。","机心久已息，此乐应有馀。","逍遥保贞素，何劳赋遂初。"]},{"t":"环翠草堂为毕思诚赋二首 其二","f":"五言古诗","c":["华构远阛阓，萧闲近郊坰。","林木布繁阴，风日有馀清。","闲来恣容与，陶然山水情。","冲襟协幽赏，岂为尘事萦。","浣花有高躅，相期崇令名。"]},{"t":"送余德禔归羊城","f":"五言古诗","c":["闻君前日来，几时别乡县。","大江咫尺间，无由一相见。","忆昔会皇都，春风二月初。","看花驰骏马，换酒解金鱼。","嬉游凤凰台，纵览鳷鹊观。","兴来动豪吟，落笔词华焕。","欢遇惜未久，暌违似参商。","君先归广海，我独向滁阳。","君今又南还，谓言忆慈母。","朝看庐阜云，暮宿西江雨。","行经十八滩，指日度梅关。","家山应不远，遥见白云山。","山中有仙人，扫花坐磐石。","闻君已归来，携琴喜相即。","授君长生诀，遗君九节蒲。","调笑碧霞里，此乐谁能如。","嗟予久别家，瞻云泪盈袖。","何日承恩回，堂前祝亲寿。"]},{"t":"圣驾幸北京率僚属父老郊迎","f":"五言古诗","c":["圣朝崇典礼，大驾重时巡。","銮舆度淮甸，驰道无纤尘。","金吾肃前驱，平原彀骑分。","日华辉宝盖，烂若五采云。","皇风被寰宇，草木亦欣欣。","欢声动黎庶，喜气腾三军。","礼文焕有光，功烈迈前闻。","幸哉睹盛事，稽首歌皇仁。"]},{"t":"晓出贡院","f":"五言古诗","c":["春闱甫竣事，此日当朝谒。","从容出院门，禁漏声未歇。","龙河泮新冰，驰道消积雪。","逶迤度九陌，窈窕望双阙。","自顾樗散材，幸陪鸳鹭列。"]},{"t":"至凤阳郡庠与徐教授王司训夜坐偶赋以下西游稿","f":"五言古诗","c":["凤阳国中都，黉宇敞弘规。","济济集群彦，文采光陆离。","适兹新雨霁，皓月烛前墀。","书帷罢弦诵，夜漏滴多时。","梧叶坠繁露，柏树起凉飔。","胜集谐夙愿，清谈转忘疲。","会晤方恨晚，暌违复在兹。","明发度淮去，烟树渺遐思。"]},{"t":"望嵩山有感","f":"五言古诗","c":["嵩少夙所慕，寤寐思见之。","今日忽在眼，群峰翠参差。","阳林耀灵景，物色光陆离。","淑气所融结，从来蕴灵奇。","未繇陟丹峤，得趣心自怡。","复怀中林士，岩栖息尘羁。","守静悟玄秘，清斋茹仙芝。","岂无中谷刍，白驹不可维。","令人重景仰，临风谩嗟咨。"]},{"t":"游新安烂柯山王乔洞","f":"五言古诗","c":["峨峨烂柯山，日夕生紫烟。","仙人启洞府，涧水导其前。","白石寒齿齿，幽篁静娟娟。","绀露泫瑶席，庆云集蕙櫋。","泠风从东来，可以散烦悁。","万变纷在目，泛览何茫然。","王事有严戒，胡能久周旋。","振衣下山去，满耳凄鸣蝉。"]},{"t":"素岩为陈炼师赋","f":"五言古诗","c":["炼师媚仙者，高蹈息尘机。","冥栖华岳中，白石敞岩扉。","猿鹤喜为侣，云烟足自怡。","朝饮涧下水，暮采岩前芝。","守道契玄妙，冲襟慕希夷。","玄风日以畅，松乔或可期。","我本烟霞侣，素心澹无为。","自婴符竹封，夙志今已违。","因为素岩咏，眷眷重遐思。"]},{"t":"登骊山有感","f":"五言古诗","c":["骊山矗霄汉，缭绕白云生。","露径绿苔老，秋林红叶明。","凭高肆遐瞩，山水互回萦。","终南亘太华，浐灞通渭泾。","三川何逶迤，千里犹掌平。","秦中百万家，俯视犹列星。","缅维天宝中，兹山擅佳名。","复道岁游幸，栖阁高峥嵘。","秋风起朝元，温泉出华清。","如何乐未终，胡尘集咸京。","一从西幸蜀，无复来霓旌。","繁华竟何在，但见山青青。","宴安古所戒，后世在当惩。","我来重登览，触景感废兴。","临文动悲诧，不尽千古情。"]},{"t":"中秋对月有怀滁阳诸公","f":"五言古诗","c":["天上秋已半，人间夜气澄。","六合静无氛，银河寒欲冰。","皓月流金波，疏星低玉绳。","虚堂集尊俎，转觉忧思增。","光摇莲炬粲，香爇篆烟腾。","嘉会固云乐，念念在亲朋。","佳期久乖阔，何时还合并。","沉思不成寐，兀坐候晨兴。"]},{"t":"长安杂诗十二首 其一","f":"五言古诗","c":["长安号天府，迤逦带河山。","爰稽古分野，正居井鬼间。","沃壤亘千里，陆海莽平川。","自昔饶物产，匪独贡琅玕。","公刘有遗风，稼穑日滋蕃。","载观西都赋，富庶难备言。"]},{"t":"长安杂诗十二首 其二","f":"五言古诗","c":["苍姬都丰镐，国祚日隆昌。","所积本仁厚，岂惟恃富强。","自后继者谁，刘汉暨李唐。","复能施德政，宜其胤祚长。","嬴政与杨隋，再传即灭亡。","福善与祸淫，天理诚昭彰。"]},{"t":"长安杂诗十二首 其三","f":"五言古诗","c":["奥区数雍州，形胜闻天下。","洪河带泾渭，终南亘太华。","褒斜接陇首，崤函扼中夏。","秦穆恃险阻，建国遂称霸。","始皇嗣遗绪，并吞靡遑暇。","不知恢至德，惟务逞雄诈。","国祚甫二传，功业竟沦谢。","孰知奉春君，能反沛公驾。"]},{"t":"长安杂诗十二首 其四","f":"五言古诗","c":["咸阳古秦地，人物誇富强。","勃蹊与谇语，礼义失其防。","粤从炎汉兴，风俗杂五方。","乡里重游侠，侈靡视为常。","阅历千百年，政教渐更张。","矧值圣明世，习俗愈淳良。"]},{"t":"长安杂诗十二首 其五","f":"五言古诗","c":["关中号形胜，古称帝王都。","四塞地固险，三辅势匪孤。","河山相表里，土壤复膏腴。","九朝迭建国，雄丽称名区。","繄昔全盛日，孰不拟黄虞。","一朝运祚去，宫殿莽丘墟。","所恃竟安在，无乃昧良图。","在德不在险，斯言诚匪虚。"]},{"t":"长安杂诗十二首 其六","f":"五言律诗","c":["闻昔未央宫，缔构极弘丽。","周遭数十里，台殿咸称是。","虽云可重威，何以训来裔。","文皇撒露台，诚足范后世。"]},{"t":"长安杂诗十二首 其七","f":"五言古诗","c":["纵目咸阳原，陵墓高嶙峋。","佳气久萧索，秋雨暗荆榛。","重泉閟玉匣，芳草埋石麟。","神灵竟何在，倏经千百春。","偶思薛平事，茫昧奚足云。","张侯有高识，允矣社稷臣。"]},{"t":"长安杂诗十二首 其八","f":"五言古诗","c":["晓出城东门，山川入遐睇。","纵观细柳营，重感当年事。","军容不入国，将军宜不拜。","棘门与灞上，无乃真儿戏。","条侯乃虎臣，足膺藩屏寄。","寥寥已千年，此事孰能继。"]},{"t":"长安杂诗十二首 其九","f":"五言古诗","c":["汉武志求仙，通天置祠具。","修茎立仙掌，云表承清露。","屑琼供晨餐，拟期寿年固。","胡为竟无成，垂老方悔悟。","颓龄竟莫驻，灵迹亦非故。","何如葆冲和，百岁或可度。"]},{"t":"长安杂诗十二首 其十","f":"五言古诗","c":["东都重经术，校雠何审详。","唐兴尊圣道，斯文赖表章。","群经刻翠琰，森列置国庠。","众目共观睹，异诸孔壁藏。","逮今数百载，字画犹辉光。","义理焕日星，万载明纲常。"]},{"t":"长安杂诗十二首 其十一","f":"五言古诗","c":["偶登慈恩塔，纵步曲江池。","蔓草萎寒露，亭台失故基。","忆昔繁华日，正当盛唐时。","胜游集群彦，文采光陆离。","姓名题翠琰，拟为千岁期。","剥落竟何在，徒使后人悲。"]},{"t":"长安杂诗十二首 其十二","f":"五言古诗","c":["隋文初启祚，经营逞私智。","竭力事浮屠，梵刹遍都市。","李唐踵遗风，崇尚亦非细。","弘兴土木工，创建极华丽。","章敬最知名，妆严乃其次。","于今总丘墟，亦足监兴废。"]},{"t":"过轘辕关","f":"五言古诗","c":["峨峨轘辕关，关门据层巘。","若非鬼斧凿，安得此奇险。","淩晨喜经过，百折路回转。","身居万仞高，目极千里远。","缑山与嵩岳，秀色互葱茜。","登临俯仰间，怀古兴不浅。","欲招浮丘公，来此共游衍。"]},{"t":"游少林寺","f":"五言古诗","c":["晨经崿陵关，道路互盘绕。","行寻少林寺，幽谷深窈窕。","风生万壑秋，日上众山晓。","鸣鞘惊走鹿，驻马闻啼鸟。","可人招提境，云气常缥缈。","苔色连阶除，钟声出林杪。","山僧喜迎客，煮茗汲清沼。","共谈达磨事，所恨知者少。","因登五乳山，纵观万象表。","群峰三十六，一一皆可了。","自谐尘外趣，顿觉心神悄。","澹然欲忘归，暂此息纷扰。"]},{"t":"发都城","f":"五言古诗","c":["维皇建有极，万邦悉来臣。","海宇久宁谧，和气盎犹春。","如何此胡孽，梗化肆凶嚚。","侵轶我亭障，虏掠我边民。","烽火照原野，羽书达枫宸。","天威赫然怒，亲征勒六军。","小臣专督运，黾勉效忠勤。","粮车若流水，载道声辚辚。","翘首望前旌，銮舆拥祥云。","桓桓大将军，感激思报恩。","帐下万貔虎，胜气薄苍旻。","喜凭国威灵，誓清胡虏尘。","行听奏奇捷，声光迈前闻。"]},{"t":"古长城","f":"五言古诗","c":["榆林青山下，云是古长城。","古人不可见，长城今亦平。","空馀饮马窟，泉水喜犹清。","村氓星散居，终岁事农耕。","矧属京畿内，无复风尘惊。","斯民亦何幸，熙熙乐其生。"]},{"t":"鸡鸣山","f":"五言古诗","c":["峨峨鸡鸣山，特立霄汉表。","烟霞增媚妩，日月光照耀。","悬崖有寒雕，老树绝幽鸟。","石梁驾双峰，仰见云缥缈。","想兹与天近，过者重来少。","炮台栖其巅，戍柝戒昏晓。","驻马肆遐观，岚光起林杪。"]},{"t":"鹞儿岭","f":"五言古诗","c":["初经鸡鸣山，倏见鹞儿岭。","肩立犹弟昆，雄秀实堪并。","岚气时相连，翠色互辉映。","悬崖险难跻，飞溜静宜听。","对此时暂留，云归四山暝。"]},{"t":"出塞四首 其一","f":"五言律诗","c":["亲征诏初下，我师今有名。","平生誇勇决，策勋在兹行。","铁衣光耀日，宝刀新发硎。","誓当献奇捷，何须请长缨。"]},{"t":"出塞四首 其二","f":"五言律诗","c":["狼烟起边烽，羽书入丹阙。","大驾事亲征，诸军奋忠烈。","虎士皆鹰腾，蓄锐伺俱发。","庙算已无遗，残胡期殄灭。"]},{"t":"出塞四首 其三","f":"五言律诗","c":["平生誓许国，绝域思策勋。","执戈奋前驱，壮志淩苍旻。","夜度黑河月，朝拂阴山云。","擒贼须名王，部落奚足云。"]},{"t":"出塞四首 其四","f":"五言律诗","c":["自小事嫖姚，亦尝逐轻车。","平生射雕手，紫塞曾驰驱。","此日应明诏，为君去平胡。","建勋在兹始，笑视金仆姑。"]},{"t":"浩亹关","f":"古风","c":["清晨发雕窝，寒气犹可畏。","倏至浩亹关，下马一长喟。","局步淩?崿，俯身历崄巇。","林深一径通，岸绝两崖对。","下窥深莫穷，仰视飞鸟外。","云萝翠成幄，杰木整如旆。","行行出窈窕，眼豁心自快。","遥瞻赤城山，历历青可爱。","念昔汉宣朝，戎羌犯边界。","充国屯浩亹，骑兵一时溃。","卓哉赵将军，画策中机会。","屯田慎边守，勋名独称最。","古人不可作，遗迹宛犹在。","此日偶经过，因之发长慨。"]},{"t":"登龙虎台","f":"五言古诗","c":["晓入居庸关，引睇龙虎台。","台因山以崇，地位何雄哉。","繄昔有元氏，舆地极九垓。","龙朔建都城，清暑岁往回。","往回此驻跸，骋望天宇开。","日色耀翠华，山光落瑶杯。","冠裳总来会，济济萃群才。","教坊呈百戏，犀象杂龙媒。","世运有隆替，遗址空崔嵬。","驰道积芳草，石磴生苍苔。","我从塞外归，到此独徘徊。","时当六月中，赤日飞黄埃。","登临协幽趣，笑挹薰风来。","玉京在咫尺，云气生蓬莱。"]},{"t":"夜梦亡弟琦觉而有感","f":"五言古诗","c":["尔从捐馆后，荏苒逾六期。","每兴同胞念，此心转凄其。","今夕是何夕，梦中□依稀。","亹亹叙乖阔，仍似在家时。","蘧然惊睡觉，此乐安□□。","□□不成寐，空有涕涟洏。"]},{"t":"□□□□□□□敬赋","f":"五言古诗","c":["□□□□□，□□□□□。","滩声自潺湲，崖壁炫青紫。","鱼濯碧波□，□□□□□。","□□□□许，鹿□差可拟。","畸人嗜幽静，卜筑近□□。","□□□□□，□□□□□。","□阴连松筠，香气杂兰芷。","尘喧□□□，□□□□□。","□□设尊罍，客去玩书史。","逍遥穹壤间，此□□□□。"]},{"t":"江南图为考功杨郎中赋","f":"五言律诗","c":["江南多好山，秀色互辉映。","人居近林麓，长年喜幽静。","好鸟鸣嘉树，驯麋卧芳径。","偶此披画图，悠然发清兴。"]},{"t":"送太医院夏吏目","f":"五言古诗","c":["灵雨洒芳甸，驰道绝纤尘。","之子献成绩，启行在兹晨。","亲朋总来饯，祖帐近龙津。","柳条已堪折，离思徒纷纷。","扁舟过淮泗，遥瞻岱岳云。","金台不日至，趋朝拜严宸。","天官应奏最，祇沐九重恩。","显擢谅可期，勖哉励忠勤。"]},{"t":"金山","f":"古风","c":["峨峨浮玉山，孤峰高几许。","孤根蟠地轴，雄势压水府。","特立天堑中，群山孰能伍。","洪涯聚鸱鹘，阴洞走鼯鼠。","上有金仙居，晨昏响钟鼓。","亭台总奇胜，水石尤险阻。","念昔韩将军，壮气猛如虎。","舟师才八千，曾此破狂虏。","复闻坡翁辈，来游恒接武。","题诗刻苍崖，字若鸾凤翥。","我昨滁阳来，薄暮宿江浒。","淩晨试一游，渡口发双橹。","维时逢七夕，炎炎值秋暑。","倏焉风雨过，凉气满天宇。","胜地喜穷探，灵迹思快睹。","扪萝历嵚岑，陟磴出林莽。","淮山在眉睫，历历青可数。","渴来饮中?，兴至醉清酤。","独立妙高台，诗成狂欲舞。"]},{"t":"金山寺妙高台","f":"五言古诗","c":["维舟金山下，飞步妙高台。","倚阑纵遐瞩，豁然怀抱开。","谁云隔一水，我喜绝纤埃。","淮南见咫尺，烟树翠成堆。","江山宛犹昨，昔人安在哉。","缅怀坡仙辈，赋咏骋雄才。","俯仰几百年，石刻荒苍苔。","不须雍门琴，对景令人哀。"]},{"t":"吕城","f":"五言古诗","c":["炎灰不复然，三国犹鼎峙。","孙郎启雄图，控地数千里。","丹阳号名镇，伯业肇于此。","吕侯膺重寄，才略真国士。","筑城漕渠壖，百雉一时起。","区区卫生聚，金汤谩曾拟。","曾未百馀年，寂寞见遗址。","春风草色青，夜雨苔痕紫。","在德不在险，斯言岂虚耳。"]},{"t":"游惠山","f":"五言古诗","c":["泛舟过梁溪，芙蓉水初冷。","折芳渡瑶涧，访竹缘修畛。","飘然陟崇冈，远目时一骋。","川原入遐瞩，一一意先领。","虚壑度松声，阴崖落云影。","秋草荒历山，露叶垂舜井。","湛陆宅久墟，榛翳道全梗。","访古情弥切，怀贤意方永。","下寻漪澜堂，因访招提境。","扫地焚名香，汲泉试新茗。","顿觉心源清，岂惟棼务屏。","重期望太湖，飞步登绝顶。"]},{"t":"拜侍读学士王公达善墓","f":"五言古诗","c":["卓哉天游翁，行高学尤富。","蚤年拥皋比，烨烨腾芳誉。","后来教成均，寻复登玉署。","上结九重知，声名益昭著。","竟赴玉楼招，哀歌闻薤露。","峨峨九龙山，今喜遂安厝。","嗟予旧同寅，道义交有素。","恒惭负明义，弗获重临顾。","遥遥许剑心，梦寐伤迟暮。","今秋来浙西，幸得拜公墓。","洁兹生刍奠，清酤渍绵絮。","空怀郭有道，不见王文度。","揾泪下荒丘，风吹白杨树。"]},{"t":"登苏州府学尊经阁","f":"五言古诗","c":["六经寓圣言，焕如日星光。","人文幸斯睹，万古明纲常。","虽云厄秦火，犹赖汉表章。","诸儒擅颛门，训诂加审详。","虽贻穿凿讥，圣道藉以彰。","阅历数百年，六朝至李唐。","昌黎崛然起，著述自激昂。","后来五星聚，奎宿生寒芒。","伟哉舂陵翁，道学起炎方。","伊洛绍正传，关闽复阐扬。","紫阳朱夫子，敷贲集群芳。","矧今圣明世，治术轶羲黄。","文风被九有，弦诵日洋洋。","惟苏实名郡，昔为魏公乡。","黉宫有杰阁，经籍旧所藏。","牙签悬万轴，蠹鱼落芸香。","予时幸观睹，如临上帝傍。","尊闻行所知，黾勉思自强。","圣谟信昭著，终身矢弗忘。"]},{"t":"陈士初母贞节诗","f":"五言古诗","c":["吴中有陈氏，诗礼著家声。","相彼绿水居，犹如德星亭。","有美如诚翁，文艺夙驰名。","早赴玉楼招，不及享修龄。","夫人属盛年，抆泪抚其婴。","空闺鸣机杼，孤灯影茕茕。","旦暮示慈训，遗孤幸有成。","喜能绍箕裘，孝行尤足称。","诸孙亦秀发，文采丹凤翎。","节义有丰报，如穫必于耕。","是家天所祐，和气盈门庭。","旌书自天下，恩光被里闳。","峨峨贞节门，华表高峥嵘。","因为贞节篇，庶以扬德馨。"]},{"t":"苏小小墓","f":"五言律诗","c":["苏姬家钱塘，槜李有遗墓。","芳姿竟何在，碑石宛如故。","光阴百岁过，声色几人悟。","可怜墓前花，娟娟泣秋露。"]},{"t":"晓发孟渚河至麻沙夹阻风雨","f":"古风","c":["晓发孟渚河，阳乌光熌烁。","黄山遥在望，中流露?崿。","海门渺何许，烟水空漠漠。","挂帆溯长江，疾如顺风鹗。","倏惊天宇昏，渐听浪声恶。","须臾聚千艘，沙渚暂依泊。","潮来洲渚平，月黑风雨作。","宵永悟秋深，天寒觉衾薄。","平生一寸心，俯仰无愧怍。","行藏付所之，原不系忧乐。","呼酒沃壮怀，江皋听鸣鹤。"]},{"t":"望黄山","f":"五言古诗","c":["黄山屹中流，此日欣盻睐。","初疑螺髫青，渐睹砥柱大。","长江来万里，混混俱此会。","潮生岚气寒，浪触雪花碎。","海门望无穷，飞鸿渺天外。"]},{"t":"晓发麻沙夹","f":"五言古诗","c":["昨暮维轻舠，萧条近沙渚。","蓬窗倚蒹葭，淅沥鸣秋雨。","晨兴喜光霁，万象争快睹。","轻帆驾顺风，如鸟新插羽。","潮来海气腥，浪起雪花舞。","行望铁瓮城，云边见楼橹。"]},{"t":"十六日晚发六合","f":"五言律诗","c":["扬舲溯长河，风物喜清美。","茫茫秋水平，淡淡暮山紫。","倏焉月东升，光彩腾万里。","孤鸿何处来，清音落人耳。"]},{"t":"范增冢","f":"五言古诗","c":["鸿门宴方酣，貔虎眼中睡。","沛公脱身遁，楚计已先懈。","徒然咍竖子，玉斗风前碎。","曲逆六出奇，喜已中机会。","乞身遽先归，疾势日危殆。","自恨失沛公，纵死恨犹在。","古冢彭城南，阅历经几代。","宝剑閟泉扃，夜夜发光怪。","妖胡来睥睨，盗取恣一快。","厚葬古所讥，斯足为鉴戒。","峨峨戏马台，适与兹冢对。","我来闲登临，怀古增慷慨。","英魂不可招，又乏椒浆酹。","长歌下山去，悲风起松桧。"]},{"t":"陵母墓","f":"五言古诗","c":["刘项方战争，雌雄犹未决。","智士虽纷纭，徒掉三寸舌。","谁知陵母贤，料事独明哲。","匪惟识所附，凛凛见奇节。","当其别汉使，吐言何激烈。","古剑飞寒光，荒冢埋碧血。","幽魂岂沉沦，耿耿比明月。","照耀穹壤间，千古常不灭。"]},{"t":"王陵台","f":"五言古诗","c":["公馆候初旦，乘轺出闉阇。","载瞻王陵台，远在青山隅。","薄言纵登览，石径来萦纡。","念昔建筑时，拟为永远图。","孰知百世后，依旧成丘墟。","遗址虽尚存，草木久荒芜。","鹤驾竟不来，岁月屡已徂。","旷视洞万古，使我增长吁。","缅邈念明训，为善乐有馀。","悠悠千载下，犹能光简书。","吁嗟骊山葬，为计一何愚。"]},{"t":"宿荏平驿","f":"五言古诗","c":["赪霞驻馀光，老树生暮色。","回风恋丛薄，清响不暂息。","解鞍憩驿庭，景物喜岑寂。","梧桐月一轮，络纬秋四壁。","起来坐徘徊，露华满庭白。"]},{"t":"谒宣圣庙","f":"五言古诗","c":["成均首善地，礼殿高穹窿。","金碧绚晴旭，松桧含清风。","秋闱方撤棘，祇谒瞻圣容。","偕行总文彦，礼度何雍雍。","仰惟天子圣，道学极尊崇。","教化广无外，黉宇遍寰中。","矧兹首善地，四方咸来宗。","英才日以盛，教化日以隆。","于赫文风振，当与三代同。"]},{"t":"游天师宫有怀张真人及吴闲闲二首 其一","f":"五言古诗","c":["都城启灵境，琳宫丽层霄。","离离万玉树，终日起祥飙。","龙虎张真人，曾此驻云轺。","虬髯赪玉颜，餐霞拟松乔。","久厌尘世居，竟赴三山招。","丹台空寂寞，云气自飘飘。","我来抚遗迹，落木风萧萧。"]},{"t":"游天师宫有怀张真人及吴闲闲二首 其二","f":"五言古诗","c":["昔有闲闲翁，名重霄汉间。","时同太乙子，林下共烧丹。","丹成跨黄鹤，一去不复还。","丰碑刻遗像，癯然辟谷颜。","年深谁复识，剥落莓苔斑。","我来喜瞻睹，不觉兴长叹。"]},{"t":"东岳庙","f":"五言古诗","c":["岱宗毓神灵，千古奠齐鲁。","层城列飞观，宝殿敞弘宇。","银榜耀绿楹，金支辉析羽。","五岳神独尊，威灵著千古。","黔黎被仁泽，感戴犹父母。","前朝崇礼秩，碑碣纷莫数。","文辞日星垂，字体鸾凤翥。","奇迹世所希，孰不争快睹。","予时北京来，炎炎值秋暑。","沐芳肃冠佩，祇谒暂容与。","松桧起凉飔，薜荔含宿雨。","遥瞻天门高，临风久延伫。"]},{"t":"谒孔林","f":"五言古诗","c":["尼父家陬乡，设教在洙泗。","从游三千人，速肖七十二。","夫何大圣人，有德而无位。","名非著一时，道实重万世。","幽幽鲁城北，高冢蟠厚地。","诸徒服心丧，三载庐墓次。","贤哉端木公，舍守凡六祀。","鲁人往从居，厥众犹栉比。","因名曰孔里，岁常供祭祀。","后来诸儒宗，讲礼亦弗替。","过鲁祀太牢，实始汉高帝。","峨峨马鬣封，阅历几千岁。","子孙来陪葬，昭穆分次第。","墓碑列低昂，丛木阴蔽亏。","森森尽桥梓，郁郁总松桧。","奇树多如云，惟楷时所贵。","乌鸟不敢栖，虎兕远潜避。","荆棘不敢生，芝草挺灵异。","仰惟尼父圣，德与天地配。","福泽何绵绵，封爵逮华裔。","昔读东游记，久矣思一至。","今幸经鲁城，瞻拜增仰企。","因过思堂前，感慨发长喟。"]},{"t":"正月十五晚在济宁发舟至开河驿偶成","f":"五言古诗","c":["扁舟溯长河，淡淡暝烟生。","野水渺无际，凫雁泛春声。","须臾华月上，川光生夜明。","摇摇泛星采，万顷玻璃平。","如坐玉壶中，毛发亦含清。","旷景与心合，孰识此时情。"]},{"t":"正月十九日至北京即事偶成八首 其一","f":"五言律诗","c":["圣皇绍丕基，抚运膺天眷。","日月垂光华，河山悉安奠。","玉帛来万方，衣冠萃群彦。","同风旷千古，六合今畿县。"]},{"t":"正月十九日至北京即事偶成八首 其二","f":"五言律诗","c":["皇风被海宇，人物咸熙熙。","藩维重方召，廊庙尽皋夔。","麟凤在郊薮，贞符协明时。","词臣司制作，盛治形歌诗。"]},{"t":"正月十九日至北京即事偶成八首 其三","f":"五言古诗","c":["都城逾万雉，甲第相绵联。","文窗夹绣户，旦夕鸣管弦。","讴歌乐熙皞，旷怀似神仙。","千金恣游衍，岂识百虑煎。","谁知杨子云，白首草太玄。"]},{"t":"正月十九日至北京即事偶成八首 其四","f":"五言古诗","c":["北京古名都，士习素豪雄。","伊昔有荆卿，畅饮燕市中。","悲歌和渐离，逸气犹长虹。","流盻四海隘，仰视浮云空。","壮志虽不就，声誉垂无穷。"]},{"t":"正月十九日至北京即事偶成八首 其五","f":"五言古诗","c":["昭王喜下士，曾筑黄金台。","玉帛贲丘樊，英杰咸归来。","剧辛与乐毅，亦足称奇才。","皇明肇鸿业，仁风被九垓。","宾兴有明诏，多士歌台莱。"]},{"t":"正月十九日至北京即事偶成八首 其六","f":"五言律诗","c":["峨峨万岁山，翠色淩苍穹。","下临太液池，上接广寒宫。","琪林炫晴旭，秀色何葱葱。","翠华或临幸，万岁乐无穷。"]},{"t":"正月十九日至北京即事偶成八首 其七","f":"五言律诗","c":["驱车入京国，周道何逶迟。","玉帛来诸侯，金汤固城池。","宫阙五云里，金碧相交辉。","图籍聚东观，文光昭璧奎。"]},{"t":"正月十九日至北京即事偶成八首 其八","f":"五言古诗","c":["予本樗散材，弱龄弄柔翰。","孤踪半天下，似为名利绊。","缪膺春闱召，京邑恣游玩。","愧无济时具，叨禄空自叹。","终宵耿忘寐，兀兀坐待旦。"]},{"t":"会同馆对雪","f":"五言古诗","c":["新阳力犹微，阴气尚郁结。","昨宵风雨来，吹作瑶空雪。","芳砌飞玉尘，虚檐落冰屑。","轩墀肃且静，对此更奇绝。","寒光耀文窗，素色映华棁。","锦帐氍毹温，醉面生绮缬。","每念沙场人，衾裯冷如铁。"]},{"t":"衍圣公留饮燕申堂","f":"五言古诗","c":["高堂极弘敞，满地绿阴繁。","爰集文翰俦，礼恭貌逾温。","堆盐罗异味，设醴出芳尊。","主宾各真率，幸有古意存。","既醉复饱德，此乐矢弗谖。"]},{"t":"同张容与登峄山","f":"五言古诗","c":["凫绎奠东鲁，翠色高崔嵬。","有时发霞采，照耀金银台。","兹游获胜览，顿觉襟怀开。","探古访灵迹，登高轶浮埃。","何当淩绝顶，翘首望蓬莱。"]},{"t":"黄石公祠","f":"五言古诗","c":["晨登谷城山，祇谒黄石祠。","偶展瓣香敬，遽兴千载思。","忆当秦运否，天地发杀机。","龙蛇起平陆，靖者当属谁。","惟公挺灵异，治乱能前知。","圮下书一篇，文义何奥奇。","子房获亲授，竟为帝者师。","汉兴仇已复，勋业高巍巍。","后来握兵人，遵用靡敢违。","功效著千古，岂但被当时。","圣朝重褒祀，春秋陈礼仪。","神灵谅昭假，赐福无终期。"]},{"t":"游小西天途中偶赋","f":"五言古诗","c":["维时日载阳，风力颇和缓。","骋望陟崇阿，渐觉生意满。","杏花红正繁，草色绿犹短。","雉鸣想林暄，鱼跃知水暖。","逍遥协幽悰，山路岂辞远。"]},{"t":"游石经寺二首 其一","f":"五言古诗","c":["孤坐不自适，言访石经山。","山峰何巍巍，矗立霄汉间。","禅扉洞然启，金碧炫晴峦。","古碑蚀苔藓，荒径杂荆菅。","贞珉镌内典，千载期不刊。","谛观悟真想，陡觉心清閒。"]},{"t":"游石经寺二首 其二","f":"五言古诗","c":["我闻小西天，境幽地殊僻。","肇基自北齐，隋师重开辟。","梵经十二部，刻石閟灵室。","有唐开元中，金仙力修饰。","香木示佳祥，神光著灵迹。","至今数百年，风致宛犹昔。"]},{"t":"光霁轩为蹇叔华赋","f":"五言古诗","c":["繄昔濂溪翁，图启太极秘。","岂惟开后学，往圣亦能继。","襟怀复洒落，人皆仰光霁。","惟子古渝彦，性资喜纯粹。","皎皎鸾凤姿，温温瑚琏器。","蚤探濂溪学，妙理独超诣。","端居澹无营，坐挹庭草翠。","灵台湛虚明，物欲岂能蔽。","光风与霁月，悠然见胸次。","愿言穷道源，直要溯洙泗。"]},{"t":"送左卫郑指挥之任","f":"五言古诗","c":["却谷富诗礼，声华著中军。","祭遵事雅歌，汉庭策殊勋。","论将岂专武，亦复尚夫文。","竹素纪遗烈，千载扬清芬。","郑君将门英，才略迥超群。","替职觐天阙，复喜归南藩。","承恩出都门，雨雪正纷纷。","扬舲过淮泗，遥望江东云。","不日度庾岭，粤山见嶙峋。","旌麾耀轩墀，锦衣拜双亲。","训武谅多暇，接引皆儒绅。","愿言竭忠赤，于以报皇仁。"]},{"t":"湖山秋夕图为礼斋郭公子赋","f":"五言古诗","c":["夕景敛馀辉，湖山喜幽寂。","桂花散清芬，松树带寒色。","玉蟾天东来，下照湖水碧。","群鸟栖未定，驯麋意閒适。","诗兴入冥搜，风致浩无极。","何当挟飞仙，长歌溯寥泬。"]},{"t":"筠雪轩为姑苏吴廷瑞赋","f":"五言古诗","c":["修筠近前楹，劲节恒在目。","朝来积雪多，风落声簌簌。","寒侵白鸾尾，冻折琅玕玉。","新音静宜听，清气端可掬。","闲歌淇澳诗，缅想筼筜谷。","何以慰雅怀，陶然醉醽醁。"]},{"t":"友清轩为江阴黄彦达赋","f":"五言古诗","c":["澄江有佳士，不为尘事撄。","所事在高洁，卜筑向林扃。","轩居喜幽僻，松梅有馀清。","苍髯屋角垂，翠羽花间鸣。","闲将绿绮弹，爱此霜月明。","悠然协清趣，孰识此时情。"]},{"t":"送广州俊都纲之任","f":"五言古诗","c":["光孝古名刹，六祖修行地。","素称大丛林，缁流若云聚。","粤从建僧司，宗风畅前裔。","尚人旧居此，蚤矣悟禅秘。","迩来授都纲，恩命实非细。","昨从北京回，天界暂留憩。","兹晨发都城，驰道雪初霁。","悬想到官时，菩提长新堤。"]},{"t":"晚翠轩为主事唐吉祥赋","f":"五言古诗","c":["亭亭百尺松，先世栽培厚。","阅历已百年，直干大如斗。","翠色干九霄，清阴连数亩。","风声响波涛，露气袭窗牖。","美人日相对，爱之犹好友。","斲苔求茯苓，采花酿春酒。","岂无桃与杏，妖艳非所偶。","何如岁寒姿，终可奈长久。"]},{"t":"挽广西钱参政","f":"五言古诗","c":["武肃有贤孙，才华信英特。","粉署腾芳声，黄堂著嘉绩。","继参广藩政，令誉尤煊赫。","炎徼仰威名，群黎沐恩泽。","方图展经济，报国竭忠赤。","一疾竟沉绵，遂作九泉客。","风悲桂岭秋，月黯薇垣夕。","庶僚承哀讣，相对动凄恻。","旅榇自南来，薤露惨行色。","窀穸谅有期，铭昭墓门石。"]},{"t":"种善堂为仁和王惟善赋","f":"五言古诗","c":["武林有佳士，医术能专攻。","一从来京师，市隐阛阓中。","济人居善药，卓有宋清风。","所居矧幽寂，梧竹纷成丛。","橘井湛秋绿，杏花媚春红。","孜孜务种善，阴德日已崇。","愿言慎终始，无亏平昔功。","它年方伎传，令誉垂无穷。"]},{"t":"梧月轩为徐公子尚絅赋","f":"五言古诗","c":["轩前有高梧，繁阴覆石坛。","修柯长百尺，宛若青琅玕。","明月天际来，下照影团团。","紫花凝露香，碧叶含风寒。","美人启窗坐，玩赏有馀欢。","素彩生席上，清声起檐端。","托根幸得所，久依金井阑。","谅非众木偶，终当栖凤鸾。"]},{"t":"梅月轩","f":"五言古诗","c":["幽轩敞虚明，况遇风露夕。","寒梅逞芳姿，皓月流素魄。","清晕满庭除，暗香浮几席。","伊人静相对，尘虑若冰释。","正宜抚瑶琴，不用吹玉笛。","长歌逋仙诗，清思自无极。"]},{"t":"浙江林参政挽诗","f":"五言古诗","c":["维公闽海彦，才名孰能先。","襟怀冰雪清，节操金石坚。","柏府久敡历，薇垣适乔迁。","岂惟风纪振，复见政化宣。","方图报圣恩，一疾遽沉绵。","夙志竟莫酬，饮恨归重泉。","余久慕英槩，忍闻讣音传。","载歌薤露词，不觉泪潸然。","幸有太史辞，煌煌贲新阡。"]},{"t":"宜澹轩","f":"五言古诗","c":["人生穹壤间，随分安厥宜。","所贵在闻道，侈靡诚可嗤。","繄昔金谷园，繁华冠当时。","一旦变荒榛，千载令人悲。","钟均将门英，冲怀慕希夷。","大羹与玄酒，此味深自知。","克守武侯训，澹泊恒自持。","啜水胜饮醪，餐冰犹茹饴。","痛洗纨绮习，思效古人为。","勖哉慎所操，远大以为期。"]},{"t":"韫玉斋","f":"五言古诗","c":["粲粲荆山英，声价逾结缘。","卞和亦何人，三献徒取辱。","维君美风仪，温温宛如玉。","怀宝不轻售，待价藏诸椟。","孚尹竟旁达，光采眩人目。","行当贡天朝，宁容久潜伏。"]},{"t":"慈训堂为王士原赋","f":"五言古诗","c":["王氏有贤母，贞节迈古人。","晨昏善教子，诲语何谆谆。","所勉在诗书，所陈在彝伦。","自爱熊丸苦，宁知鹤发新。","子今赖有成，素履夐出群。","竭力致孝养，期报教育恩。","诸孙亦秀发，佩服矢弗谖。","高堂揭华篇，歌咏归儒绅。"]},{"t":"美邹烈妇","f":"五言古诗","c":["史妇邹氏女，红颜盛芳年。","良人隶戎籍，荷戈去防边。","兵尘方澒洞，杀气亘中天。","仓皇失所依，已不望生全。","一朝竟遭掠，剑戟罗满前。","宁死不受污，遇害归黄泉。","白璧虽无瑕，鸾镜岂复圆。","至今坟上木，清风犹凛然。","我为纪贞烈，留待太史编。"]},{"t":"送受益黄先生会试","f":"五言古诗","c":["夫君蓝溪后，瑜■蕴荆璞。","结发抱遗经，道源溯伊洛。","春秋夙所嗜，义例尊笔削。","朅来试秋闱，摛藻扬景铄。","奋身青云中，丹桂喜高擢。","春闱期在迩，万里赴京国。","大廷拟敷对，早晚膺宠渥。","勉哉树勋名，勿负平昔学。"]},{"t":"思贻堂为钱宣昆仲赋","f":"五言古诗","c":["海虞有钱氏，学行众所推。","虽膺九重眷，所蕴未及施。","嗣子守遗训，夙夜罔或违。","裕家务勤俭，存心复仁慈。","善庆逮后昆，惠泽被孤嫠。","诸孙信英特，双璧联光辉。","孝敬心切切，友爱情怡怡。","素志在显扬，拟学古人为。","沉潜在经籍，跬步循矩规。","为善益自力，声誉恒昭而。","藏修一室中，华扁名思诒。","芸香袭书幌，墨花浮砚池。","有志事竟成，矧遭圣明时。","奋迅谅有日，远大以为期。"]},{"t":"草庭为蹇公子赋","f":"五言古诗","c":["美人嗜贞素，居地喜幽僻。","春融土脉动，庭草纷如织。","茸茸媚烟姿，袅袅交翠色。","光风自无边，生意恒不息。","开窗纵清玩，万虑若冰释。","缅怀濂溪翁，终日观太极。"]},{"t":"碧霞丹房为道士王立中赋","f":"五言古诗","c":["有美学仙侣，癯然辟谷颜。","身披鹤氅衣，头戴芙蓉冠。","寻真得秘诀，归住碧霞间。","玄馆既深邃，洞门亦萧闲。","安垆识火候，终日炼还丹。","朱砂杂铅汞，宝鼎龙虎蟠。","九转丹若成，金箓名不刊。","群真拟相候，同访三神山。"]},{"t":"藏春楼","f":"五言古诗","c":["子家近太湖，书楼喜弘丽。","水木自清华，云山见迢递。","维时春载阳，淑景政明媚。","林花绽嫣红，堤柳袅新翠。","春光虽无涯，藏之有馀地。","埙篪协淳音，沉檀蔼芳气。","潜心在典坟，亹亹穷道义。","蠹鱼落芸香，科斗寻古字。","齐云与落星，徒尔贮歌妓。","何如藏春好，生意永无替。"]},{"t":"对月焚香图为户部左郎中赋","f":"五言古诗","c":["琳宫矗璇霄，上有三素云。","明蟾流清辉，虚坛净尘氛。","况兹秋露凉，丹桂有馀芬。","道人学仙侣，修炼志何勤。","对月焚宝香，临风朝玉宸。","不闻步虚声，倏觉夜将分。"]},{"t":"题弋阳王知县尚㻞族谱","f":"五言古诗","c":["人生本乎祖，此乃先哲言。","譬木有其本，譬水有其源。","源深流则长，本固末自蕃。","山阴有王氏，乡邑称名门。","阅历世代久，谱谍幸斯存。","昭穆既弗紊，支派一何繁。","诸孙宰弋阳，德性犹春温。","涖政日多暇，修谱贻后昆。","匪惟知所重，宗族赖以敦。"]},{"t":"和胡祭酒村居即事韵","f":"五言古诗","c":["赤日方赫炽，临流咏风涟。","轩窗既弘敞，水木尤澄鲜。","泳波见游鯈，抱叶鸣新蝉。","炎蒸倏焉涤，凉气恒满前。","忆昔河朔饮，犹鲸吸百川。","人生行乐耳，矧遇承平年。"]},{"t":"小瀛洲为礼部侍郎王公行俭赋","f":"五言古诗","c":["我闻瀛洲居，景物一何好。","晨曦耀琼林，夕露泫瑶草。","清严犹秘府，图籍纷浩浩。","中有列仙儒，颜容长不老。","玉堂视草回，幽致协冲抱。","所尊鲁麟经，所黜汉鸿宝。","进秩贰春官，礼乐在论讨。","皇猷资黼黻，人物归品藻。","圣眷日弥深，况际时熙皞。","其乐如道山，何须访三岛。"]},{"t":"水竹居为王公赋","f":"五言古诗","c":["华构敞高明，况复临清池。","碧水自泠泠，箓竹何猗猗。","日出镜光净，风来翠羽披。","多君擅清致，对此情自怡。","不为孺子歌，喜诵武公诗。","丹衷素自许，劲节能坚持。","粤从历华近，上受列圣知。","伫看昼锦回，所居愈光辉。"]},{"t":"送云南龙佥事致仕回桂林","f":"五言古诗","c":["桂林古名郡，风俗殊不薄。","人才接武兴，往往多卓荦。","洪武壬申冬，我忝持教铎。","君在诸生中，有如鸡群鹤。","不惟工词藻，素履复端恪。","一朝试棘闱，丹桂喜高擢。","犹珠方离渊，如玉才出璞。","文采光烨然，万目争骇愕。","春闱不得志，鼓箧游太学。","蜚英六馆中，才识愈弘博。","发轫为府推，能声已昭灼。","及为绣衣使，风采动台阁。","亦尝按属郡，霜威撼山岳。","廉名彻宸聪，陟官承宠渥。","初佥浙江宪，到处询民瘼。","绳纠在愆缪，激扬别清浊。","调官至滇南，岂惮路绵邈。","为政务抚绥，不专事击搏。","远人获安堵，终岁乐耕凿。","往来仕途中，邂逅情如昨。","炊粳共朝餐，剪韭供夜酌。","追思旧游者，晨星已落落。","君近北京来，一见即欣跃。","谓言遂悬车，琴书载归橐。","此别会何时，使我怀抱恶。","乡关行在望，尧山见磅礴。","家人候锦还，日日占喜鹊。","功名今已遂，归去有馀乐。"]},{"t":"赵仲穆拂郎马图为护卫指挥徐广渊赋","f":"七言古诗","c":["忆昔前元全盛时，四海人物咸熙熙。","拂郎远国奉职贡，进到神马尤权奇。","是何生此异毛骨，双蹄雪白身抹漆。","肉騣碨礧七尺高，骏气淩风欲超忽。","朝夕立仗丹墀下，白玉之鞍覆黄帕。","渥水神驹何足珍，瑶池八骏真其亚。","吴兴王孙艺绝伦，闲将缣素为写真。","笔踪慌怫韦夫子，精妙不减曹将军。","吁嗟王孙不复作，纵有骏骨谁能貌。","方今天厩尽龙媒，比与斯图宛相若。"]},{"t":"天育骠骑图为都指挥使韩公赋","f":"古风","c":["唐代君王少巡幸，赤泽岸边马成阵。","后来蕃息虽已多，天育之驹号神骏。","圉人牵来不敢骑，矫矫龙性汗血姿。","君王见此志骄逸，天下龙媒思致之。","闲厩有官从此始，宁禁中人衣金紫。","四十三万若云屯，其中未必皆骥子。","一朝渔阳鼙鼓来，内外监牧俱烟埃。","翠华摇摇西幸蜀，骠骑此时安在哉。","谁能写真传后世，逸态雄姿无乃是。","鸣呼，騕袅龙媒今岂无，时无孙阳诚可吁。"]},{"t":"骢马图为宪使黄存诚作","f":"七言古诗","c":["大宛神驹世所稀，独有此马称权奇。","方瞳棱棱开紫电，修尾飒飒摇青丝。","闻道骅骝乃其亚，未觉千金满高价。","长鸣已自空冀北，骏足宁终淹枥下。","每见常随绣衣使，白玉玲珑压双辔。","有时朝退凤楼西，道上行人远惊避。","逸态雄姿不可攀，朝并暮越须臾间。","会见巡历周九域，还随骐骥入天闲。"]},{"t":"鹰兔图为宪佥花子春赋","f":"七言律诗","c":["霜风猎猎沙草黄，苍鹰疾视金眸光。","纤纤玉爪试一击，道傍狡兔无留藏。","我亦平生爱神骏，不独当年有支遁。","何当臂汝向平原，黠鼠妖狐俱扫尽。"]},{"t":"金人出猎图为宪使黄存诚赋","f":"七言古诗","c":["胡地秋高多雪霜，金人校猎来沙场。","毡车百辆随戎王，桓桓虎士争跳梁。","紫骝叱拨杂骕骦，雕鞍银镫红绒缰。","其中者谁膂力强，黄髯似戟双瞳光。","弯弓雄视隘八荒，瞥然驰过青山傍。","狐兔奚足污镞铓，仆姑一发殪白狼。","海东之鸷材最良，畜养日久思奋扬。","脱鞲直上云间翔，金眸玉爪不可当。","鴐鹅群飞摩青苍，竦身击之绝其吭。","雕鹰四出势愈张，血洒平芜多毙伤。","戎王对此喜欲狂，举头大笑天茫茫。","岂恤士马冻欲僵，且沽潼酪浇枯肠。","归来开宴罗酒浆，毳裘狐帽分两行。","高烧银烛排红妆，琵琶枨枨间笙簧。","戎王嗜酒犹渴羌，诸酋起舞迭进觞。","上下胥庆乐未央，不知华月生东方。"]},{"t":"杜子美寻芳图为指挥姜仲文赋","f":"七言古诗","c":["杜鹃叫破空林烟，锦官城外春无边。","碧鸡坊头酒新熟，黄四娘家花正燃。","少陵老子动幽兴，蹇驴破帽东风前。","同行者谁二三辈，襟怀洒落如神仙。","醉归不觉日已暮，小桥争度催吟鞭。","图中光景宛如昨，知是天宝开元年。"]},{"t":"罗稚川山水为桂林郡守孙伯贞赋","f":"七言古诗","c":["郭熙之后有稚川，妙画往往人争传。","醉来乘兴扫轻素，笔下萧飒生云烟。","天台雁荡宛相似，仙楼佛阁纷满前。","春风瑶草发幽涧，暮雨藤萝垂古阡。","危桥半空度羸马，断崖千尺飞寒泉。","扁舟一叶欲何往，人家多住沙岸边。","牛羊鸡犬自成趣，武陵何必求神仙。","我亦平生好清致，出山自笑归无缘。","还君此画三叹息，罗浮东望心悠然。"]},{"t":"归去来图为岑太守赋","f":"七言古诗","c":["渊明先生冠世贤，志节凛凛能俱全。","江左文章日萎薾，楚声独数归来篇。","归来三径喜犹在，未应环堵成萧然。","柴桑酒熟巾可漉，菊花满眼黄金钱。","阳秋特书晋甲子，清风一枕羲皇天。","图中丰采虽恍惚，平生心事谁能传。"]},{"t":"哀余淮南","f":"古风","c":["安庆城，何其长。","城北山兀兀，城南水汤汤。","下流带闽浙，上流襟江湘。","余侯昔日守此邦，遭时孔艰多陆梁。","群凶倡乱陷淮楚，贼锋远来谁敢当。","余侯仗义思报效，日夜并力修城隍。","许国何曾顾家室，奋刀直欲歼豺狼。","手提精兵才半万，身作藩维蔽一方。","屡陈忠义激将士，闲引诸生升讲堂。","人人思奋不携贰，奈时不支良可伤。","贼围四面势愈亟，扶病裹创赴敌场。","檄书不通外无援，困守孤城经七霜。","阖门节义古来少，应为世道扶纲常。","圣朝有诏重褒美，复敕立庙长淮傍。","睢阳淮南与浔阳，千秋万古同流芳。"]},{"t":"哀李江州","f":"七言古诗","c":["元纲告衅天柱倾，太白夜夜摇光晶。","陈胜之徒起相继，首陷颍蔡次鄂荆。","浩浩妖氛塞天地，不意来薄浔阳城。","浔阳江淮一保障，李侯忠义能支撑。","完城练卒矢杀贼，君臣义重视死轻。","十万红巾夜飞渡，晓觇山前皆贼营。","羽书沉沉烽火急，霜露肃肃边笳鸣。","挺身大小百馀战，斩刈无算贼胆惊。","鼓鼙无声日光薄，阴风西来膏血腥。","奈何中外失救援，皇天后土呼不应。","挥戈跃马决一战，临终骂贼口不停。","英英烈气排山岳，落落芳名照汗青。","人生自古谁不死，侯今虽死犹如生。","我来泊舟谒祠下，奠以寒泉荐菊英。","坐招五老歌楚些，山光水色含馀情。"]},{"t":"过浯溪读磨崖碑","f":"七言古诗","c":["禄儿搆难陷两京，乘舆西幸九庙惊。","河东二十四列郡，曾无一人如杲卿。","汾阳淮南信英杰，义旗指挥僭伪平。","东宫即位在灵武，乾坤再造海宇清。","二圣重欢意方洽，两宫流言吁忍听。","元子文章严且简，太师笔势纵复横。","我时泊舟断崖下，寻读石刻半灭明。","摩挲不尽千古意，东风吹雨天冥冥。"]},{"t":"题致仕尚书严公震直所藏苏东坡墨竹","f":"七言古诗","c":["坡仙写竹称第一，往往人间见真迹。","金钗折股锥画沙，妙笔当年信无匹。","此图寻常位置工，露叶云梢分淡浓。","高堂香清白昼静，似觉满座生秋风。","我昔乘槎渡江水，行遍潇湘五千里。","黄陵庙前秋雨寒，九疑山头暮烟紫。","苍梧刺天云茫茫，上有绿竹参天长。","云中紫实已应结，便欲因之邀凤凰。","别来陡觉星霜换，每忆旧游生浩叹。","今朝客里重披图，空对亭亭霜雪干。"]},{"t":"题方方壶武夷山水图","f":"七言古诗","c":["金门羽客方方壶，作画不减高尚书。","锦囊玉轴幸披睹，乃是武夷山水图。","武夷只在建溪上，翠岫璚峰郁相向。","半空楼阁架层崖，一叶渔舟弄新涨。","闻有仙人驻紫烟，自呼白鹿种芝田。","九曲棹歌谁复听，幔亭风景世犹传。","我亦平生亲画史，落笔时时追董米。","方壶况复夙所慕，偶睹斯图心独喜。","看罢令人逸兴新，清泉白石许谁邻。","世上神仙何处问，人间却忆杜徵君。"]},{"t":"题赵子昂双松图","f":"七言律诗","c":["吴兴王孙画最工，挥毫写出双乔松。","爽飒寒声杂风雨，蜿蜒曲势蟠蛟龙。","千年老干犹屈铁，阅历光阴饱霜雪。","严冬十月百卉空，始信人间有奇节。"]},{"t":"雅集图为许谦赋","f":"七言古诗","c":["东坡先生百世师，落笔顷刻成珠玑。","桃巾紫裘坐者谁，晋卿王公美丰仪。","二姝夹侍双鬟垂，风韵自是名家姬。","丹阳蔡君性坦夷，座隅凝伫真若痴。","何人为写渊明姿，云是龙眠李伯时。","子由傍睨方注思，鲁直挥箑来何迟。","碧虚擘阮众所推，少游嗜之犹渴饥。","米君南宫书法奇，千丈石壁蟠蛟螭。","仲至仰首频嗟咨，髼头捧砚空朵颐。","圆通谈禅世莫知，巨济谛聪忘其疲。","岂独山水供游嬉，亦有童稚相追随。","石床棐几宁别施，唯陈琴尊与鼎彝。","诸公之乐乐在兹，至今图画形歌诗。","击丸蹴鞠徒尔为，如此雅集胡不宜。"]},{"t":"题学录周士谦梅花手卷","f":"七言古诗","c":["周君手持梅花卷，访我求赋梅花歌。","几回展玩不忍舍，自觉满眼生阳和。","我家南海五千里，罗浮山下常经过。","翠禽无声春寂寂，花下独酌欢颜酡。","记曾乘骢度庚岭，喜有清致供吟哦。","千花万花饱霜雪，一树两树交藤萝。","亦曾西湖泛夜月，孤山玉立高嵯峨。","时闻暗香出修竹，又见瘦影横清波。","江南梅花看欲遍，胜赏不似罗浮多。","追思往事宛如昨，人间岁月惊飞梭。","临风抚景生浩叹，才薄奈尔梅花何。","玉堂相见定有日，且呼绿酒倾金螺。"]},{"t":"凤台歌寄宝邑亲旧","f":"楚辞体","c":["亭亭凤凰台，屹立南海湄。","相传有神仙，骑凤曾到之。","翠旂羽葆纷杂遝，鸾笙十二吹参差。","鱼龙起听海波立，白鸐上下相追随。","一从仙人去不返，几番春草荒台基。","秋风吹老紫竹实，夜月空挂梧桐枝。","我时读书凤台下，与君同结沧洲期。","常常登临恣游乐，呼酒共酌黄金卮。","酒酣悲歌谩吊古，豪气万丈舒虹霓。","南溟俯观一杯小，罗浮侧望群峰卑。","眼周八极想高举，欲跨黄鹄云间飞。","有时吐言作珠玉，散落犹恐寰中知。","细询往事增慷慨，令人徒忆丁令威。","我闻唐虞三代时，麒麟在郊凤来仪。","乃知灵物产治世，神仙之说何足稽。","当今大圣人，德化溢九围。","醴泉甘露效祥瑞，芝房天马形歌诗。","凤兮性本灵，来仪勿迟迟。","醴泉可供饮，竹实堪疗饥。","莫向丹丘老文采，好向明廷览德辉。","凤兮凤兮久不来，使我怅望增遐思，使我怅望增遐思。"]},{"t":"十台怀古 其一 姑苏台","f":"七言古诗","c":["吴王行乐登高台，凤绡翠幕重重开。","更深歌舞宴西子，飘飘丝竹云边来。","渡溪铁骑纷如簇，台上犹歌乌夜曲。","曲声未断越兵来，一旦欢娱梦蕉鹿。","蛾眉零落归何处，声色迷人孰能悟。","千年遗址百花洲，犹说吴王旧行路。"]},{"t":"十台怀古 其二 章华台","f":"七言古诗","c":["灵王意气淩寰宇，十万雄兵辟疆土。","登临更有章华台，睥睨中原瞰荆楚。","穷奢极丽非良谋，纵乐日向高台游。","皓齿能歌细腰舞，蛾眉宁识人间愁。","一朝霸业归萧索，江上游魂招不得。","夕阳衰草栖寒烟，伤心忍过荒台前。"]},{"t":"十台怀古 其三 朝阳台","f":"七言古诗","c":["瑶台百尺临江上，水色山光共环向。","君王行乐年复年，凤阁龙楼隐层嶂。","神娥归来暝色寒，佩声缥缈青霄间。","朝云暮雨竟何在，苍枫丹桂盈秋山。","当时谁擅高唐赋，宋玉才高欣际遇。","往事悠悠不可论，台前老树西风怒。"]},{"t":"十台怀古 其四 黄金台","f":"七言古诗","c":["子哙沽名堕庙社，燕昭信是真王者。","黄金不惜筑高台，郭隗能言千里马。","一时云集俱英豪，剧辛乐毅非儿曹。","建功已酬国士报，声名不让燕山高。","春秋义战由来少，何限生灵膏野草。","王风不作周道东，慷慨令人怀二老。"]},{"t":"十台怀古 其五 戏马台","f":"七言古诗","c":["重瞳仗剑东方来，霸气欲压彭城摧。","噫呜啐咄止如此，日思飞鞚游高台。","击鼓撞钟誇侈靡，五色龙文望中起。","阴陵失道空自伤，不见当时千万骑。","东城决战心犹雄，草木惨惨生悲风。","沛公自是真天子，看渠百战徒刭死。"]},{"t":"十台怀古 其六 歌风台","f":"七言古诗","c":["高皇仗义诸侯归，沛中白日神龙飞。","三秦已定四海一，图治宁敢忘宵衣。","大风歌来山岳动，父老闻之泪如涌。","此时何不歌南薰，慷慨尊前似矜勇。","翠华不来台已荒，满林松桧声悠扬。","后人登临空叹息，怀古之情岂终极。"]},{"t":"十台怀古 其七 望思台","f":"七言古诗","c":["湖城城头云黯黯，望思台成悔何晚。","一从金犊去无踪，几度春风岁华远。","武皇用人何太轻，江充小吏机谋深。","东宫冤气贯星斗，白日紫汉生层阴。","神仙楼观连云起，有术难招戾园鬼。","恩深舐犊恨无穷，目断湖城隔秋水。"]},{"t":"十台怀古 其八 铜爵台","f":"七言古诗","c":["漳河河边起铜爵，烜赫威声穷朔漠。","台中妖姬盛如云，凤帐鸾帏翠罗薄。","清歌一曲秋风前，飘飘吹入青云间。","台前老树恨未已，至今叶染啼痕斑。","当年艳骨归何处，鸟能清歌柳能舞。","欲持斗酒酹英雄，寂历西陵暗风雨。"]},{"t":"十台怀古 其九 凤凰台","f":"七言古诗","c":["梧桐日暖生紫云，綵凤飞下嗈嗈鸣。","台中之人不可见，日餐白玉歌长生。","凤去台空朝复暮，五色霞明玉京路。","云间仙乐按宫商，天上銮坡集鹓鹭。","瀛洲别来岁月遥，何时再赴群仙招。","醉呼斗酒酹太白，卧听花前碧玉箫。"]},{"t":"十台怀古 其十 淩歊台","f":"七言古诗","c":["宋皇江左开新国，别业淩歊高百尺。","三千歌舞恣欢娱，十二阑干映空碧。","羽盖鸾旌几度来，香风满座琼筵开。","凤笙龙管听未毕，台前落日飞黄埃。","醉后昏昏凭玉几，遥望台城才百里。","可怜风致易凄凉，一段繁华付流水。"]},{"t":"题真率会图","f":"七言古诗","c":["洛阳胜景天下稀，况值元丰全盛时。","满城甲第列卿相，朱檐画栋生光辉。","人间二月春光好，花枝冥冥照晴昊。","且将诗酒慰良辰，何用轮蹄踏芳草。","真率之会乐最真，为具务简宁嗤贫。","五人七百有馀岁，同醉花前能几春。","洛中此会应无比，闻自唐朝乐天始。","由来叙齿不序官，要令风俗归淳美。","先辈悠悠不可呼，谁写仪形归画图。","甫申间气秀不绝，如此风流何代无。"]},{"t":"清流关","f":"七言古诗","c":["清流山高横碧落，崖石棱层犹铁削。","忆昔南唐始开凿，据守形势真险恶。","殿前虞候有雄略，麾兵飞度谁敢格。","晖凤东门就擒缚，乃知恃险古所薄。","当年意气归萧索，惟有青山宛如昨。","大明德教溢六合，文恬武熙颂声作。","四方无虞闲警柝，关吏何劳守鱼钥。","我常登临驻骓骆，呼酒悠然引孤酌。","怀古时时发大噱，万里天风起寥廓。"]},{"t":"醉翁亭怀古","f":"七言古诗","c":["滁城西南多好山，峰峦矗立青云端。","智仙好事择幽胜，构亭乃在山之间。","山回路转六七里，曲涧潺湲弄春水。","酿泉泻出两峰来，亭子翼然平地起。","醉翁襟度非常人，时来开宴罗众宾。","宴酣之乐乐最真，山殽野蔌纷前陈。","醉翁之意不在酒，好水好山渠所有。","胸中豪气吐虹霓，笔下文光射星斗。","一去人间知几年，山光水色尤依然。","废址荒凉春雨里，断碑剥落秋风前。","我来登临无限意，欲谈往事心先醉。","方今四海歌治平，亭构尝怀嗣翁志。","他日重看复故基，眼前突兀增光辉。","会须更秉如椽笔，为写磨崖百尺碑。"]},{"t":"孝鸟行美黄孝子","f":"古风","c":["嗟孝乌，尾毕逋。","结巢向高树，养此黄口雏。","一朝雏成毛羽觕，终日返哺鸣呜呜。","海滨有黄生，适与乌性符。","堂上有亲垂白颅，此心直欲慕子舆。","晨昏竭孝养，亲心自怡愉。","光阴不留亲已殂，白日惨澹天模糊，泪血已竭眼欲枯。","高冢峨峨临海隅，清风足愧枭獍徒。","吁嗟黄生孝义俱，至行不但孝乌如。"]},{"t":"精卫辞哀陈烈妇","f":"古风","c":["东海有精卫，衔石填海死。","海枯石复烂，此恨何时已。","天目山崩王气消，北风夜退钱塘潮。","崖山新称行在所，万里兵尘涨九霄。","南海有烈妇，能守陵母节。","泪血满衣裾，泣与儿决别。","万古纲常日月明，尔当尽忠吾尽节。","黄木湾头风雨来，扶胥海口浪如雷。","此时孤愤同精卫，一堕沧溟竟不回。","沧溟之深有时竭，烈妇之名应不灭。"]},{"t":"哀洸口","f":"古风","c":["哀洸口，天为愁，海风吹鬓寒飕飕。","五羊城头天狗堕，南汉伯气应全收。","天吴海鲸恣吞噬，漠漠妖氛遍南裔。","皇风闻已畅中原，岭海疮痍待湔洗。","禹馀宫使输忠言，主聪不悟诚堪怜。","舟师甫自屯洸口，此身已殒谮人手。","至今山下有遗祠，日色惨淡行人悲。"]},{"t":"战韶阳","f":"古风","c":["战韶阳，日光薄，朔风南来撼山岳。","梅关已碎淩江枯，斗大孤城竟谁托。","寒芒烛地狼星光，边声彻夜交锋铓。","老奴潜缒城竟覆，残兵散走如群羊。","虎头将军面如铁，义胆忠肝逾激烈。","仓惶巷战接短兵，三尺龙泉耀霜雪。","誓战死，无偷生，竟死不辱勤王名。","崖山猛士多如雨，谁似韶阳战有声。"]},{"t":"孤雌吟","f":"古风","c":["有鸟有鸟心最灵，雌雄终日相和鸣。","同哺黄口雏，羽毛犹未成。","一旦雄且死，雏亦不复生。","孤雌绕林号，闻者涕欲零。","彼枭竟何为，侧目思相陵。","谁知孤雌心，宁死不辱贞。","彼枭倏远逝，安栖了无惊。","更有张门何节妇，空闺只影守孤灯。"]},{"t":"孝节行","f":"古风","c":["金石有销毁，孝节宁容亏。","妾为何家女，二亲蚤背违。","一从归李门，抚育恩最慈。","老姑偶罹疾，药石弗能治。","饮泣吁彼苍，刲股炼为糜。","糜进疾幸瘳，窃庆获所依。","爰念合卺日，年纪甫及笄。","上堂奉翁姑，入室哺婴儿。","春秋洁蘋藻，旦暮治枲丝。","女红分所专，中馈乃其宜。","无何失所天，凄恻空泪垂。","寒风吹短发，茕茕守空帷。","矢心若皎日，匪石可转移。","官府备咨访，上达九重知。","有诏下旌表，束帛加赐遗。","恩宠匪徒锡，无乃重民彝。","乡邦耆彦嘉孝节，纪述应有琼琚辞。","乌头双表虽已摧，至今令誉恒昭而。"]},{"t":"王维辋川图为襄城伯李公赋","f":"七言古诗","c":["开元进士王摩诘，文艺当时妙无匹。","诸王礼待若师友，赋咏相酬有裴迪。","大开别业蓝田间，终南溪壑相回环。","千寻瀑布飞寒练，万叠层峦拥翠鬟。","古木藤萝垂鹿栅，濯濯驯麋意间适。","琅玕萧森竹里馆，苔钱堆积宫槐陌。","南坨北坨归眺望，胜槩咸誇辋口庄。","人家几簇依林麓，辋水百道通桥梁。","往来半是烟霞侣，路绕羊肠知几许。","辛夷花残昨夜风，茱萸叶长连朝雨。","孟城坳前景最幽，携琴策蹇从嬉游。","偏爱奚童知养鹤，更说有谁能饭牛。","斤竹岭头天气暖，华子冈前莎草短。","芰荷香近临湖亭，松桧阴连文杏馆。","攲湖风来生碧波，捕鱼艇子轻如梭。","泥深古涧青芹老，水落长滩白石多。","波光微茫兼柳浪，落日轻烟起渔唱。","何人危坐把纶竿，有客清谈倚书舫。","辋川胜景十有馀，百年之后成荒墟。","空留陈迹在人世，谩有芳名传画图。","襄城李公能鉴画，犀轴牙签满高架。","独爱斯图笔法精，购之更不论其价。","我来谛观诗兴浓，此身如在蓝田中。","华堂泚笔为公赋，飘飘神思起鸿濛。"]},{"t":"幽谷","f":"七言古诗","c":["天宁寺前是幽谷，暖翠晴岚纷在目。","云昔欧阳公所开，凿泉筑亭种花木。","闲携宾从宴其间，鸟哢泉鸣当丝竹。","当时赋咏总名流，万丈文光起林麓。","一从公后几百年，芳草萋萋春自绿。","阴崖白昼走鼯鼠，古涧寒泉饮麋鹿。","余因暇日喜游览，五马騑騑度溪曲。","废址闲披荆棘寻，断碑自剥莓苔读。","何须访古重凄恻，对酒高歌送黄鹄。","方今圣人隆盛治，海宇黎民喜丰足。","嗟余德薄才复疏，祇荷天恩忝为牧。","何当筑亭兼凿泉，题诗远嗣前贤躅。"]},{"t":"谢三氏教授文时中惠楷木杖","f":"七言古诗","c":["我闻楷木出孔林，不知何人手亲植。","深根蟠地逾千载，翠色参天过百尺。","枯梢有时落风雨，人间得之争宝惜。","诚如灵寿出恩赐，不数桃榔来异域。","先生何从获此杖，一旦寄来承厚德。","奇纹分明若桃竹，劲节铿锵类金石。","提携终日不忍舍，宝之奚啻百金值。","奉寄高堂白发亲，扶老定应资尔力。"]},{"t":"北邙山","f":"古风","c":["北邙之山何其高，春雨年年生野蒿。","山上古坟纷莫数，岁远年深不知主。","墓道之碑多不存，空见石羊兼石虎。","只今山下多新阡，曾见何人挂纸钱。","松楸麦饭古来重，此事惟属儿孙贤。","因经北邙山，高歌空感慨。","漳河隔岸是西陵，陵前松柏今安在。"]},{"t":"龙门","f":"七言古诗","c":["洛阳山势互联络，独有龙门称险恶。","不知何年鬼斧凿，两崖壁立犹铁削。","水之东注孰敢遏，奔流直与黄河合。","春来洪涛相喷薄，鱼龙变化争飞跃。","我时西游初至洛，驻马临观履峎崿。","寻读石刻将苔剥，铁画银钩宛犹昨。","登临自愧无新作，把酒风前浇磊落。","浩歌仰观天漠漠，万里悠悠见孤鹤。"]},{"t":"金谷园","f":"七言古诗","c":["齐奴豪奢世所无，大开金谷城西隅。","花间构亭走石渠，晓日光射珊瑚株。","绮罗围香拥名姝，诗酒或复来文儒。","放浪剧饮朝达晡，东风三日吹不苏。","自谓百岁常欢娱，岂知运去命与俱。","可怜楼前啼绿珠，繁华一旦如华胥。","人间俯仰岁易徂，但见遗址栖烟芜。","吁嗟齐奴不可呼，五马何尔行踟躇。"]},{"t":"渑池会盟台","f":"七言古诗","c":["王风不作游说兴，苏张之辈纷纵横。","区区会盟非一所，独有此台能著名。","忆昔嬴秦誇智力，虎视中原非一日。","关东诸侯多向风，况乃邯郸居咫尺。","秦赵二王同日来，会盟直欲登高台。","瑟声才罢缶声作，军声四面欢如雷。","秦本无心偿赵地，赖有相如多气义。","奈何季世取灭亡，似怪当时璧为祟。","人间俯仰成千年，台基依旧青山前。","登临怀古意无限，西风满树鸣寒蝉。"]},{"t":"鸡鸣台","f":"古风","c":["函关之东形势好，谁筑高台临大道。","鸡声寂寂台久荒，极目平原暗秋草。","昔在七国争雄年，田文好客谁能先。","手挥黄金若土苴，珠履门下常三千。","西入咸阳曾未久，几乎委身雄虎口。","机谋已遂幸东还，狗盗鸡鸣誇益友。","早使文知重贤士，当时不堕嬴秦计。","徒窃狐裘献幸姬，间关出走真儿戏。","文但好客能轻财，大义不明良可哀。","岂不见郭槐昔年称国士，燕山便筑黄金台。"]},{"t":"华山歌","f":"古风","c":["巍巍泰华山，磐礴奠西方。","金精孕灵异，形状非寻常。","孤高拔地五千仞，三峰秀出北斗傍。","乾坤开辟几万载，但见山色恒苍苍。","云梯石磴之险不可以径上，仰见铁縆络石生寒光。","游人扳缘若猿狖，下瞰绝壑魂飞扬。","崄巇历尽至平坦，琳宫贝阙何辉煌。","金芝瑶草纷莫数，琼林珠树森成行。","水帘千尺捲晴雪，丹灶白日凝玄霜。","仙风吹下玉井莲，花瓣岂止十丈长。","世人见之不敢拾，但觉满地生天香。","吁嗟乎，泰华之胜有如此，况遇异人过后名逾彰。","昔闻十六仙，餐霞当糇粮。","一朝功成游碧落，祥鸾瑞鸐同翱翔。","复闻希夷公，高卧白石床。","紫泥丹诏徵不起，幽梦直要追羲黄。","至今遗迹宛然在，岁月已远亭台荒。","我从关东来，见山喜欲狂。","淩晨登绝顶，举目天茫茫。","诸山平地若培嵝，齐州九点犹豪芒。","蓬莱云气恒在目，王京千里遥相望。","欲招瀛州仙，同此乐徜徉。","雕盘擘麟脯，玉斝分琼浆。","双吹紫鸾笙，乘风游帝傍。","愿将万寿献天子，永令四海歌时康。"]},{"t":"宣圣手植桧","f":"七言古诗","c":["宣圣殿后手植桧，枝叶团团宛如盖。","青霄耸干近百寻，厚地蟠根知几代。","重重白昼布繁阴，瑟瑟虚檐度清籁。","异质肯随凡卉变，奇材独受高人爱。","当年老树久摧残，旁茁孙枝今幸存。","扶持自是神明力，长养偏承雨露恩。","冬来不改冰霜操，春去犹含苔藓痕。","九畴之诗人共爱，南宫之颂时所称。","我闻大别有古柏，黛色参天二千尺。","神鬼英灵长为护，风云变化应难测。","大禹之功久不磨，素王之德终无极。","圣泽流芳可并传，作歌为刻琅玕石。"]},{"t":"峄山","f":"古风","c":["亭亭绎凫山，秀色钟乾坤。","峰峦拔地几千丈，雄势直欲排苍旻。","传闻秦始皇，昔日曾东巡。","銮舆驻其下，禋祀昭礼文。","山巅立石纪功德，李斯小篆时所珍。","人间阅历几千载，字画剥落谁能分。","不惟秦碑久寂寞，琳宫梵刹迹亦陈。","丹崖翠壁宛然在，春花秋月年年新。","复闻其阳产孤桐，枝叶团团生紫云。","其材之良世所重，制为宝琴音独淳。","我愿持之献天子，坐令四海歌南薰。"]},{"t":"晓发王庄驿至固镇驿时风雪方霁","f":"七言古诗","c":["霜风连日生寒威，冻云糊天天为低。","雪花飞来大于掌，江山万里增光辉。","天鸡初号雪花止，玉树琼林半空起。","雪深路涩马行迟，狐裘迎风寒似水。","须臾曈昽开晓晴，烂银一色摇光晶。","炊烟乍出飞鸟过，依稀遥见霸王城。","驿使相迎慰寥落，山殽野簌供杯酌。","地垆火暖氍毹温，寒气虽严殊不觉。","仕路驱驰岁月赊，每因风雪倍思家。","何日承恩归故里，逍遥林下赋梅花。"]},{"t":"天平山","f":"七言古诗","c":["天平之山高插天，晴岚暖翠纷满前。","白云梵宇久寂寞，范公祠堂犹俨然。","山畔一峰名卓笔，半露棱层苍石骨。","天教秀色壮东吴，高出群山表奇特。","我时放舟山下过，为寻古迹攀云萝。","试从绝顶一眺望，诸山满眼青如螺。","最爱范家坟墓好，石马石羊藏碧草。","平生喜读义田碑，此日登临豁怀抱。"]},{"t":"登吴山谒胥祠因望海潮","f":"七言古诗","c":["属镂抉目吴东门，白日不照忠臣冤。","身浮鸱夷入水府，配涛作神恨始伸。","迄今二千有馀载，庙食吴山恒不改。","回思宰嚭肆谗徒，瞬息浮荣竟何在。","邦人事神诚意多，击牲酹酒杂笙歌。","神能阐灵慰民望，白马红衫腾素波。","我时谒神到祠下，极目西陵景潇洒。","潮头一线海门来，谁道钱王弩能射。","涨空银浪须臾平，水天一色涵虚明。","祠前徙倚空怀古，眼底越山无数青。"]},{"t":"观岳鄂王像","f":"七言古诗","c":["虎头将军面如玉，手执麟经衣戎服。","生绡一幅几百年，神采光荧射人目。","忆昔南渡谁谋臣，中兴之将推何人。","将军奉诏总戎律，壮志誓拟清中原。","义旗所经民安堵，丈八蛇矛马如虎。","钢刀斫胫拐子空，千里惊奔逐狂虏。","偃城城边飞战尘，三军胜气腾如云。","朱仙镇上势方锐，指日可平戎虏群。","捷书才奏遭谗口，赐环竟殒奸人手。","五国城头日色昏，金人相酌平安酒。","百战经营一旦空，惟馀史册表孤忠。","焚香再拜睹遗像，古庙飒飒生悲风。"]},{"t":"银瓶娘子辞","f":"楚辞体","c":["平生长在深闺里，无由上书见天子。","父兮有冤向谁理，手抱银瓶沉井底。","井枯瓶烂心不移，此事惟有天公知。","一门忠节古所稀，百世庙食礼所宜。"]},{"t":"葛岭行","f":"七言古诗","c":["湖阴葛岭称佳丽，山色波光总来会。","咸淳师相当国年，择胜因来开甲第。","石础团团列绣楹，绮窗雕户光晶荧。","香厨驼峰出翠釜，美人银甲弹瑶筝。","半闲堂中清昼永，日照珊瑚瓶水冷。","槐影横窗午簟凉，荷香满院风帘静。","五日轮舟一入朝，湖山佳处乐逍遥。","边情庶政无心理，乐听谀言志愈骄。","自矜勋德无能过，岂料欢娱变奇祸。","木棉庵下风声哀，黯淡滩头月光堕。","葛岭繁华一旦空，遗基废址长蒿蓬。","湖山此日依然好，多少游人感慨中。"]},{"t":"玉津园怀古","f":"七言古诗","c":["玉津园在南屏下，金碧煌煌起台榭。","清泉文石满春山，异卉名花宛如画。","流尘不飞天气和，龙旗葆羽频来过。","半空丽曲闻歌吹，十里香风飘绮罗。","是时太师专国柄，黩武穷兵启边衅。","罪盈恶满速天诛，玉津园中渠殒命。","天目山崩王气残，乐游一旦梦魂安。","白雁南来秋已暮，西风蔓草露华寒。","经行忍说前朝事，山色犹颦旧时翠。","恨杀韩家三世孙，名园翻作凄凉地。"]},{"t":"居庸关","f":"古风","c":["我闻居庸关，形胜天下奇。","太行西来此盘礴，峰峦万叠青参差。","中通一径四十里，石磴曲折尤崄巇。","羊肠鸟道固云险，较此未必能逾之。","自从辽金辟中土，积世刬凿方平夷。","初闻单车仅可度，后见列骑堪并驰。","当今圣化被万里，此关矧复居京畿。","虽云壮士守鱼钥，商贾来往纷如丝。","丹崖翠壁愈奇胜，清泉白石堪娱嬉。","我来督运遂登览，自拂崖石题新诗。"]},{"t":"饮马长城窟","f":"古风","c":["淩晨度榆林，饮马长城窟。","旧传窟边多白骨，云是秦时筑城卒。","窟中泉已清，无复昔时腥。","不见古人迹，空照今人形。","征马往来少曾断，饮处才乾看又满。","长城今在疆域中，马来不绝泉无穷。"]},{"t":"郎山","f":"古风","c":["郎山高，高刺天，危峰崄磴愁攀缘。","仰看高崖覆石穴，穴口至今存破船。","想初山前潴巨浸，水退之后成原田。","崖边石痕乃牵路，沧桑之说诚非传。","市廛遗迹已难觅，积沙淤没经千年。","道傍残碑宛犹在，汉隶剥落苔痕藓。","兹山雄特孰与肩，北通朔漠邻燕然。","后人于此列亭障，往往树栅当其巅。","只今圣化大无外，胡羯远遁无腥膻。","山头烽堠高且坚，此日永不生狼烟。"]},{"t":"掘甘草","f":"古风","c":["宣德城南风日好，川上原来产甘草。","长镵短钁争取之，嚼咽香甘誇国老。","岂期生杂恶草根，草根相类应难分。","寸茎入口致身毙，此物谁知能误人。","君不见黄精野葛产同穴，采者还须要精别。"]},{"t":"凿冰行","f":"七言古诗","c":["风沙漠漠日色黄，粮车已驻青山傍。","山前泉流汲已竭，仆夫来告心遑遑。","或言草间地卑湿，其下或有坚冰藏。","闻者欣然争发取，果获积块凝寒光。","纷纷辇至竞烧爨，锤斧剖击声琅琅。","铜锅瓦釜试新火，顷刻俱成蟹眼汤。","煮雪曾闻瀹佳茗，消冰今见炊黄粱。","茶香仅能止渴吻，饭熟政喜充饥肠。","南人睹之自惊异，北客视此犹寻常。","谩将毫楮纪所见，要知朔土殊炎方。"]},{"t":"云州歌","f":"七言律诗","c":["云州迤南好风土，高下川原足禾黍。","云州迤北天气寒，五谷不生民食艰。","胡羌俗与中华别，水草逐居食凭猎。","云州南去足农耕，充国曾此破先零。"]},{"t":"李陵台","f":"七言古诗","c":["汉家将军文且武，一点丹心期报主。","提兵深入单于庭，转斗无前气如虎。","五千健儿俱战没，西望长安泪如雨。","家声已坠强偷生，北面甘心作降虏。","赋诗已送子卿归，握手河梁意良苦。","此心应拟作明月，归照茂陵陵上土。","当时论录赖司马，大义犹能著千古。","生为汉臣葬胡地，白草黄云岂其伍。","乌桓城外有荒台，阅历人间几寒暑。","偶来登览访遗踪，读罢残碑意悽楚。"]},{"t":"闻笳","f":"七言古诗","c":["乌桓城外多风沙，何人月下吹芦笳。","笳声相传十八拍，拍中曲调今谁识。","大荒阴沉月色明，呜咽中含无限情。","凄凉蔡姬别虏意，哀怨胡儿恋母声。","咀徵含商声转急，飒飒悲风动毛发。","此时听罢夜方阑，独倚辕门看太白。"]},{"t":"江陵沙市","f":"七言律诗","c":["江陵城南好沙市，北贾南商总来聚。","舟航日夜怕南风，赖有黄潭可藏避。","近市人多临水居，美人卖酒常当垆。","往来皆说沙市好，饭有香粳馔有鱼。"]},{"t":"巫山神女祠","f":"楚辞体","c":["石为础兮枫为柱，梅为梁兮萝为宇。","朝行云兮暮行雨，空山寂寥兮谁其与语。","奠椒浆兮荐芳芷，进女巫兮笙竽盈耳。","目盻盻兮杳冥，瞻翠鸾兮云里。","郁阳台兮山陬，竖灵旗兮来游。","风肃然兮云收，冀少留兮夷犹，无遄返兮使我烦忧。","桂花发兮露零，秋山空兮月明。","玄猿哀兮白鹤鸣，怅望不及兮使我凝情。"]},{"t":"阳台","f":"七言古诗","c":["襄王巡游乐无度，鸾旗直指巫山路。","群臣扈从多如云，宋玉才高擅词赋。","高唐赋罢人何处，空有高台锁烟雾。","梦中之事是耶非，为雨为云自朝暮。","翠华东归竟不来，山色青青宛如故。","花开花落年复年，杜鹃啼老台前树。"]},{"t":"瞿塘歌","f":"古风","c":["蜀山发岷峨，支派何其繁。","连峰沓嶂到夔峡，两峰对立高为门。","白盐与赤甲，万仞明朝暾。","长江贯其中，水出非一源。","其南通越巂，其西来吐蕃。","浩浩纳众流，浊浪声豗喧。","势挟天地转，怒作雷霆奔。","天教滟滪遏不住，雪花飞舞洪涛翻。","黑石与黄户，险恶难具论。","舟人鱼贯牵百丈，观者胆掉惊神魂。","忆昔神禹疏导初，石壁犹存旧凿痕。","长江东流不少住，形胜独数瞿塘尊。","蚕丛凫翳旧开国，据有蜀土称雄藩。","粤从炎精丧，僭窃闻公孙。","至今白帝城，相望馀颓垣。","后来刘豫州，建国图中原。","三顾起卧龙，复此驻军屯。","至今八阵图，历历迹犹存。","自后僭伪者，琐琐奚足云。","元季夏明氏，恃险负皇恩。","天威赫然命六军，六军饮马川江浑。","王师乘胜克西蜀，铁锁已断来降幡。","皇风远畅清妖氛，雪山冰谷回春温。","信知在德不在险，诚如古人之所言。","群雄割据竟何在，依旧老树啼寒猿。"]},{"t":"经浮滩观瀑布","f":"七言律诗","c":["山中夜来风雨恶，晓见奔流出岩壑。","千尺浑如组练飞，满空又似珠玑落。","舟行渐近声转雄，听来恰与春雷同。","扁舟蹩然江上去，回望云边垂白虹。"]},{"t":"铁索桥","f":"古风","c":["灌阳西接羌夷路，岷江湍急舟难渡。","昔人以竹为索桥，风雨飘淋岂能固。","献王因之用意深，改造不惜千黄金。","挽拖巨石出山麓，叠作厚址依江浔。","铁柱东西列相向，铁縆平施逾百丈。","木板横铺若砥平，夷夏之人任来往。","我军千里戍松潘，长说岷江渡最难。","自从铁索桥成后，馈运之人咸喜欢。","君不见驱石为桥桥岂成，掷杖为桥空有名。","何如此桥坚且久，献王之功垂不朽。"]},{"t":"石经","f":"七言律诗","c":["六籍自遭秦火惨，后来多用石刊经。","循行难觅汗青迹，校字喜看科斗形。","化去不随煨烬灭，残来犹带藓花馨。","收藏原在文翁学，谁见当年旧制铭。"]},{"t":"青城山歌","f":"楚辞体","c":["锦官城西青城山，道释往往栖其间。","琳宫梵宇半陈迹，瑶草昙花空自闲。","禅翁说法伏黑虎，仙子朝元骖翠鸾。","天花时落石坛静，灵药夜捣玄霜寒。","复闻长林中，亦有幽求子。","眼看富贵等浮云，心薄功名如弊屣。","人间荣辱了不闻，几度天书徵不起。","山有芝兮隰有丰，幽泉发窦锵玲珑。","饥餐渴饮足以保厥躬，乐逍遥兮无穷。","人间此景亦罕逢，何须远寻鹫岭兼崆峒。"]},{"t":"望峨眉山","f":"七言古诗","c":["峨眉之山高万丈，鸣鹤青城郁相向。","峰峦喜与太白齐，似与西川为保障。","郁葱秀色根鸿濛，望之如云浮碧空。","嵚岑峛崺不可上，千岩万壑来清风。","白云之巅梵王殿，五色光华望中见。","天晴云散看龙归，日出鸟呼知佛现。","山中原来富奇植，灵药仙葩人罕识。","丛生瑞竹粲如金，树结甜瓜坚似石。","势连雪岭极西方，六月常见飞严霜。","积雪长年消不尽，始知境界真清凉。","白水丛林半山起，楼阁参差綵霞里。","普贤灵迹世无双，苏子雄文今有几。","扁舟拂晓到嘉陵，眼中独爱兹山青。","召命有期不得往，试凭诗句讯山灵。"]},{"t":"雪山歌","f":"古风","c":["若有昆崙之西岷峨阴，天文上属井与参。","危峰列嶂高万仞，色映银汉光沉沉。","忆初康回触折天柱时，娲皇炼石补天多苦心。","故将太白作天骨，斯山独与同嵚崟。","势连西域白不断，极目万里皆瑶簪。","阴风号寒滕六过，琪花六出成琼林。","飞鸟不敢度，矧有哀猿吟。","光晶熠耀可望不可近，使人对此毛发寒森森。","其中何所有，冰蛇长十寻。","雪□与雪鼠，谷底藏尤深。","万年坚冰消不得，岂畏夏日能流金。","几回霜台闲骋目，独爱爽气清予襟。","何当乘风问真宰，请化此雪为甘霖。"]},{"t":"徐太守雪梅为副都御史周公铨赋","f":"七言古诗","c":["昔人画梅谁最奇，独数花光与补之。","二人去后几百载，至今声誉犹昭而。","当涂太守清江彦，能与梅花写生面。","呵笔方惊冰在毫，临池又觉香浮砚。","朔吹号寒冻未消，琅玕石上粲琼瑶。","雪盈老干昭奇节，阳动孤根长气条。","南枝几朵先春白，不比群芳后时发。","生来原自有精神，老去犹能存骨格。","玉堂茅舍咸相宜，风尘不染冰霜姿。","声名已居三友行，香影岂负逋仙诗。","内台使君事高洁，耿耿襟怀凛冰雪。","赋咏欣同水部何，披图静对心怡悦。"]},{"t":"龙洲书舍为佥都御史张公纯赋","f":"七言古诗","c":["荆南风气原清淑，江水西来出巴蜀。","龙洲乃在江中央，乔木千章蔼晴绿。","闻道君家在此居，经籍收来万卷馀。","漆书字古见蝌蚪，芸草香清落蠹鱼。","藏修偏宜地幽寂，轮蹄不来苔藓碧。","谪仙昔日爱匡山，范子当年住长白。","何如龙洲景最奇，风来新水生文漪。","岂惟净渌可涤砚，政要临清堪赋诗。","长年读书不出户，六籍流观自朝暮。","孔颜乐处信能寻，濂洛微言应蚤悟。","一朝擢桂步青云，廷对才华迥出群。","科名已听闻当宁，竹素还期纪异勋。","乘骢衣绣时巡历，总说襟怀似冰蘖。","荣升都宪振台纲，报国常存寸心赤。","自号龙洲知几春，书舍年来入梦频。","此日应偿读书志，清风拟绍古名臣。"]},{"t":"送陈颐庵上四川省墓","f":"七言古诗","c":["列圣相承崇孝治，恤典之加及勋贵。","恩颁命数原自殊，凤诰龙章日星丽。","勋臣今重平江公，一心报国存精忠。","锦城旧日开戎卫，先陇峨峨马鬣封。","先陇暌违越年岁，引领西南独歔欷。","阴森宰木今已拱，几度孙枝长新翠。","君为公嗣真宁馨，代行展省摅孝诚。","墓题嘉赠夫人号，碑刻中朝太史铭。","闻说佳城地尤吉，聚气藏风固难得。","钟奇毓秀永无穷，门户光华应今日。","公之勋德诚可嘉，君之义气还堪誇。","他年定有如椽笔，为表淮西忠孝家。"]},{"t":"百雀图为余通政可才赋","f":"七言古诗","c":["码碯坡前冬雪晴，琅玕竹外梅梢横。","晓来群雀喜翔集，或斗或啄兼和鸣。","其中一鸟与众异，洁白翎毛雪霜似。","长养初蒙卵翼恩，冲飞原有云霄志。","伊谁笔法妙入神，缣素写来能迫真。","况兼景物更奇绝，生意满前诚可人。","良工旧说黄筌辈，熟玩斯图亦云最。","宝绘之堂迹已陈，对此令人增慷慨。"]},{"t":"徐太守雪梅为巡抚江西侍郎赵公新赋","f":"七言古诗","c":["黄堂太守画最奇，爱写寒梅雪里姿。","繁花绽玉暗香动，老干屈铁苍苔滋。","任教玉笛吹夜月，自有春意生南枝。","肯随桃花媚时俗，素与松竹同襟期。","精神何惭仁老笔，香影不负逋仙诗。","魁名已在百花上，金鼎调羹当有时。"]},{"t":"题赵松雪画洛神及写洛神赋","f":"楚辞体","c":["繄思王入觐东归兮，日严饬其徒御道。","伊阙与景山兮，瞻鸾旌之飞度。","遇宓妃于洛川兮，缥缈隔乎烟雾。","倏飘忽其若神兮，见淩波之微步。","从湘滨汉皋之神女兮，俨众灵之来聚。","采明珠而拾翠羽兮，纷杂遝而容与。","虽眷眷于淑美兮，将奚以达乎衷素。","临川流而凝伫兮，嗟幽冥之异路。","偶琼珰之来献兮，岂徽音之能悟。","耿良宵而忘寐兮，遂怅然而归去。","念此事之莫稽兮，所可重者思王之赋。","览松雪之图写兮，觉神怡而目注。","历百祀而如新兮，诚在人之珍护。","聊肆玩以自适兮，又奚用深究乎其故。"]},{"t":"兰翠轩为陈廷璋赋","f":"楚辞体","c":["彼美人兮貌清扬，开轩适近茹溪傍。","依稀辋川之风景，恍惚浣花之草堂。","雨过娟娟修竹净，风来馥馥崇兰香。","时看霏翠落虚牖，或见水气生寒光。","终朝相对尘虑息，如游九畹浮三湘。","神閒气和乐自然，飞梦不到名利场。","谢家兰玉信堪拟，蒋氏三径还可方。","累世相承在诗礼，应是前人庆泽长。"]},{"t":"山水图为褚嗣良赋","f":"七言古诗","c":["昔分符竹知永阳，居民乐业歌时康。","环滁况复好风景，醒心丰乐曾尚羊。","追游僚友总文雅，紫薇泉上同飞觞。","幽谷朝来云气白，琅琊雨晴山色苍。","树藏古刹暝烟合，花落三湖春水香。","龙蟠菱溪号名胜，林下今谁开草堂。","别来俄惊十四载，空有遗爱留甘棠。","兴来闲写旧游景，褚生得之喜欲狂。","装潢成轴索题咏，新诗赋就情何长。","江云淮树恒在目，还忆欧公旧醉乡。"]},{"t":"聚星堂","f":"七言古诗","c":["句曲之墟有陈氏，诗礼相承敦孝义。","高堂华扁名聚星，先世相传太丘裔。","忆昔荀氏称八龙，元方兄弟能与同。","二家子弟总英特，致令列宿昭苍穹。","盛事流传千百载，此堂之名恒不改。","西掖文光贯斗牛，德星午夜联辉采。"]},{"t":"华阳道隐为罗济能赋","f":"楚辞体","c":["三茅之山仙所都，华阳洞在山之隅。","丹房药室秘灵异，洞天之名诚不虚。","彼美人兮学仙徒，卜筑近爱华阳居。","当门列岫耀圭璧，满地白石堆琪玗。","杜门少与尘事接，终日闲观鸿宝书。","或时采芝度溪谷，或时招鹤来庭除。","兴阑高卧北窗下，松门瑟瑟鸣笙竽。","唤醒十载江湖梦，长啸一声山月孤。"]},{"t":"襄城伯李公桃花马歌","f":"七言古诗","c":["四平诸孙今总戎，爱马喜得桃花骢。","首如渴乌竖两耳，目犹夹镜明双瞳。","肉騣碨礧汗流赭，满月点作胭脂红。","饱食常怀玉山下，顾影尚忆瑶池中。","有时骄嘶似矜宠，顿令庭院皆春风。","紫燕赤骠乃其亚，一出能令冀北空。","总戎报国存精忠，况有神骏来遭逢。","云台勋业立可致，不让当年卫霍功。"]},{"t":"题方壶画","f":"七言古诗","c":["龙虎仙山在何处，玄馆琳宫锁烟雾。","人间昨夜风雨过，瑶草琼芝长无数。","金门羽客方方壶，早年曾在山中居。","身如野鹤无定着，心与浮云同卷舒。","平生喜作南宫画，醉墨淋漓恣挥洒。","峰峦远近分淡浓，笔意神奇多变化。","斯图自信超凡流，眼前景致清而幽。","树昏似觉云初起，石润应疑雨乍收。","神乐道人能鉴识，得此宝之犹重璧。","方壶仙去已多年，龙虎风光宛犹昔。"]},{"t":"送医官陈义成之任","f":"七言古诗","c":["太丘闻孙忠孝俱，平生喜读轩岐书。","医人每收十全效，种杏已成千百株。","今年被荐来京国，新授医官承宠渥。","缙绅祖饯出都门，别酒香凝金错落。","潞河雪霁冰澌流，好风催发沙棠舟。","南经铁瓮趋吴郡，东度钱塘望处州。","括苍山色青无数，归马能谙旧行路。","悬知三月到家时，细雨落花春已暮。"]},{"t":"孟浩然图为工部郑侍郎辰赋","f":"七言古诗","c":["灞桥雨雪初霁时，策蹇近自都城来。","飘萧乌帽任风欺，携琴童子能相随。","平生隐操人所知，不意何事游京师。","鹿门山色空参差，襄阳耆旧今有谁。","茹溪钱君笔法奇，写出当日风流姿。","郢州刺史亭久隳，丹青谁复如王维。"]},{"t":"五老听松歌为严贡士赋","f":"七言古诗","c":["我昔扁舟泛彭蠡，五老峰峦望中起。","兴来飞步上层巅，万壑松声聒人耳。","清如绿绮调冰弦，潺潺石涧鸣寒泉。","和如洞庭张广乐，珊珊环佩来群仙。","雄如昆阳破劲敌，铁骑奔腾响金革。","壮如钱塘八月潮，巨浪洪涛互冲激。","须臾听罢风已停，千林万树寂无声。","此时尘虑若冰释，一段襟怀如水清。","美人家住匡山麓，饱听松涛响岩谷。","自从折桂上青云，归梦时时到书屋。","妙龄勋业宜勉之，昼锦荣归应可期。","山中猿鹤拟相候，还听松声似旧时。"]},{"t":"题冯寺丞所藏李龙眠九歌图","f":"七言古诗","c":["红云辉辉昭玉宇，紫宫之中神独处。","大少司命播洪钧，万汇生成咸得所。","扶桑霞明天欲曙，龙辀东来从真侣。","凝情遥睇云中君，烟水微茫隔洲渚。","湘灵瑶瑟久不闻，山鬼啾啁啼夜雨。","国殇沉沦河伯逝，谁致兰殽荐芳醑。","繄昔三闾心独苦，托此微词期悟主。","鱼腹幽魂不可招，九歌闻来转悽楚。","区区忠诚孰能识，紫阳辨之深见许。","龙眠居士画更精，想像写来宁有谱。","风环月佩锵琳琅，翠辇鸾旌拥干羽。","天狼无光殪狐矢，白鼋腾波神物举。","杜衡青青兰芷馨，遗佩何人恣容与。","辛夷之车山下来，赤豹文狸导雄虎。","阴阳鬼神纷杂揉，祭赛相传楚风土。","笙箫钟鼓间琴瑟，巫能安歌觋能舞。","千年往事似足稽，景象恍如亲所睹。","信知此画妙入神，几度披图谩怀古。"]},{"t":"玄一丹房为邢彦广赋","f":"古风","c":["玄一子，家广陵。","中心静，双眼青。","几年踪迹半天下，寻师学道求长生。","归来丹房结构成，铅龙汞虎勤炼烹。","归根性命道已悟，抱玄守一心何诚。","神宇自廓然，俗念无由兴。","视彼颠冥徒，如醉犹未醒。","玄一子，志清静，慕仙灵。","细穷玉笈文，期书紫府名。","他年功就拟轻举，群真有约游蓬瀛。"]},{"t":"赵大年江村秋晚图为襄城伯李公赋","f":"七言古诗","c":["赵家王孙画最奇，缣素流传争宝之。","江村秋晚图更好，树色湖光无不宜。","农家渔梁路幽静，好似王维辋川景。","杨柳风来晓岸凉，芙蓉露下秋波冷。","芦苇萧萧烟满汀，征鸿无数上青冥。","何人独得玄真趣，日向茅茨自下罾。"]},{"t":"王孟端古木古竹石为工部郑侍郎赋","f":"七言古诗","c":["王郎之画今已稀，笔法宛若云林倪。","修筠晴翻翡翠羽，老树光亚珊瑚枝。","风霜阅历见奇节，雨露长养成幽姿。","岩岩一石亦雄特，秀色满眼生华滋。","冬官亚卿性嗜古，公暇常把斯图披。","我来纵观意怡悦，忆在阆苑瀛洲时。"]},{"t":"题蹇叔华米南宫山水图","f":"七言古诗","c":["生绢一幅何其长，图中景物犹三湘。","云树模糊生暝色，烟波明净澄寒光。","九疑南岳遥相望，白云缥缈山苍苍。","岩边有路到芝峤，林下何人开草堂。","东华红尘飞不到，信知此境犹仙乡。","雨晴沙渚萑蒲绿，风起岸汀兰芷香。","扁舟一叶竟何往，疑是米家书画航。","予生素多山水癖，安得载酒同尚羊。","米家元晖画最良，笔法高古非寻常。","清风寥寥孰可继，此卷喜君能宝藏。"]},{"t":"碧梧轩为严公子赋","f":"楚辞体","c":["君家奕叶居茹溪，骥林高与青云齐。","当轩尽是碧梧树，秀色在目恒萋萋。","萋萋菶菶真堪爱，静坐钩帘喜相对。","日转清阴生嫩凉，露晞密叶明新翠。","不用栽依金井阑，轩前地位尽宽闲。","莺声出林春昼永，鹤迹满径苔花斑。","国朝名卿称乃祖，赫赫勋华耀寰宇。","乔木千章拥故居，至今人说尚书府。","君家世德不可当，况逢四海歌时康。","梧兮梧兮善培植，拟见乔枝栖凤凰。"]},{"t":"题襄城伯李公所藏草虫手卷","f":"古风","c":["圣朝勋贵襄城公，经史韬略蟠心胸。","平生识鉴最精诣，法书名画能兼通。","闲来示我草虫卷，披玩自觉心神融。","奇花异卉各殊类，琼蕤翠蔓纷成丛。","淡黄浓绿间浅碧，物色满眼皆秋容。","葡萄实悬马乳紫，枸杞子染丹砂红。","芣苢花残芥叶老，青莎何事犹芃芃。","霜筠可人挺奇节，凛凛若存君子风。","坡前土滋新雨霁，琅玕石润光玲珑。","蜣螂蝼蛄总来集，亦有蚱蜢兼蚕螽。","螳螂蜥?恣跳趯，䗂蝓蝼蝈相追从。","玄蜩解蜕夏已过，莎鸡振羽秋将中。","蜻蜓蟏蛸逐蚊蟆，蛱蝶蜾蠃随蛾蜂。","腐虫僵蚓萃群蚁，虾蟆欲拟饥肠充。","前代何人工草虫，毫端能窃造化工。","顾丘葛侯称妙手，缣素往往留遗踪。","斯图不知作者谁，精致自信超凡工。","翾飞蠕动与生植，真物细较靡不同。","想当研吮丹粉时，运心直欲超鸿濛。","苟非精意与神会，安得妙迹传无穷。","世间一艺尚如此，何况学业非专攻。","偶因观此司至理，呼酒吸尽玻璃钟。"]},{"t":"青云轩为罗宗润作","f":"古风","c":["青云轩，南海湄。","绿窗洞然启，云山见参差。","轩中之人冰雪姿，文采晔晔珊瑚枝。","月中仙桂亲折得，归来轩子增光辉。","明年会试赴春闱，青云平步应有期。"]},{"t":"兰桂双喜图为监生马骥赋","f":"楚辞体","c":["君不见晋谢安，十年不出居东山。","一朝声华著江左，群从子弟犹芝兰。","又不见窦谏议，阴德原来真罕比。","挺生五子联芳名，当时曾拟燕山桂。","崇兰丹桂时所嘉，托根多近忠良家。","若非主家擅芳誉，谁问桂芳兰茁芽。","乐庵马翁诗礼裔，况复高情爱清致。","芸香满室书在床，桂树当门兰绕砌。","春风淡荡日载阳，崇兰郁郁含烟光。","紫茎竞秀见奇质，碧萼乍吐闻幽香。","郊墟生凉雨初霁，桂树团团实堪爱。","珠葩万点粲黄金，老叶千层张翠盖。","翁兮对此心自怡，儿孙娱侍皆英姿。","谢兰窦桂足堪并，和气蔼蔼充庭闱。","子能承颜奉甘旨，复喜潜心事经史。","昔曾擢桂登蟾宫，又见观光游璧水。","志大宁甘安小成，尚拟对策登明廷。","省亲暂尔归南海，都门祖饯皆儒英。","此行到家秋已暮，丹桂著花兰欲吐。","蹁跹綵服拜翁前，喜鹊查查在庭树。","知子平生怀远图，文采烨烨珊瑚株。","古人事业立可致，岂负少年勤读书。"]},{"t":"寿萱堂为颜宗赋","f":"七言律诗","c":["堂上慈亲双鬓皤，阶前萱草青如莎。","根荄阅历岁年久，花萼沾濡雨露多。","游子承恩到家早，膝下称觞綵衣好。","寸心难以报春晖，愿萱与亲长不老。"]},{"t":"题蒋院判家山水图","f":"七言古诗","c":["大峰小峰堆翠鬟，景致好似龙潭山。","桃花流水远廛市，昔有仙人来炼丹。","一朝功成簉鹓斑，屡承恩宠瞻天颜。","良方岂但传金匮，妙剂应能苏世瘝。","胡为仙游竟不还，空见野墅留人间。","董氏杏林原自好，苏家橘井何尝乾。","映门森森总桥梓，绕砌烨烨皆芝兰。","凭谁写归图画看。","满眼云气生层峦。","书香绵延庆泽远，医院有子称能官。","我怀仙人不复见，几回对此增长叹。"]},{"t":"虎图为礼部张尚书赋","f":"七言古诗","c":["壮哉于菟山之陲，踞视二子心若怡。","金晴夹镜玉爪利，斑斓文采生光辉。","有时一吼山石裂，腥风怒捲红叶飞。","行人辟易百兽遁，自信不敢当雄威。","伊谁妙笔能绘之，生狞猛烈看愈奇。","今时希睹包家画，后世犹传荆国诗。"]},{"t":"三骏图","f":"七言古诗","c":["王孙画马师韩干，此疋权奇见应罕。","疑是长杨较獦回，五老满身流赭汗。","近时作者任月山，真迹往往传人间。","骊黄青骢凡二疋，苑内呈来初卸鞍。","吁嗟三骏非凡质，当时曾荷孙阳识。","自入天闲沐主恩，煌煌天驷联奎壁。"]},{"t":"董原春江游览图为主事顾谦作","f":"七言古诗","c":["北苑笔意妙入神，写出一段江南春。","山如螺黛青隐隐，水似鸭绿光粼粼。","中流泛舟者何人，綵旗皂盖来缤纷。","林边游骑复杂沓，小桥曲涧通江津。","东风淡荡吹芳尘，荷亭草阁明朝暾。","柳垂青琐散金缕，花落苍苔成锦裀。","人生行乐须及辰，况值二月韶华新。","主宾相忘意欢洽，祇恐江头天色昏。","亦有农家住山麓，夫妇日夕勤耕耘。","豳风之诗久不作，孰识当年民俗淳。"]},{"t":"拱秀堂为李安御史作","f":"七言古诗","c":["浮梁田西多好山，峰峦矗立青云端。","宪台李君世居此，长溪叠嶂相回环。","修筠绕屋琅玕润，落花满径苔钱斑。","四时秀色恒在目，终日自喜钩帘看。","蛾黛横空山色媚，翠涛度壑松声寒。","有时读书不出户，六籍穷讨饥忘餐。","胸中文章粲星斗，笔下词藻生波澜。","一从擢科官执法，绣衣白简光朝班。","信知地灵产人杰，岂但泉石堪盘桓。","故山猿鹤好相候，承恩衣锦行当还。"]},{"t":"崔白鹅为驸马赵公题","f":"七言律诗","c":["羽毛䬏飔双掌赤，磊落奇姿骋雄特。","兴庆池中得隽归，欢声已遍长安陌。","斗罢梳翎向大堤，雪花消处净无泥。","此时风格谁能写，喜有濠梁崔子西。"]},{"t":"永思堂为钱孟常赋","f":"七言古诗","c":["武肃裔孙纯孝士，痛慕双亲形梦寐。","高堂华扁名永思，铁画银钩日星丽。","双亲谢世今几年，先茔宰木栖寒烟。","天台世系从来盛，序伦堂基犹俨然。","亲容寥寥无复睹，日夜哀思泪如雨。","蓼莪忍诵重衋伤，风木才闻转酸楚。","光阴迅速不可追，萱花已谢椿枝摧。","秋霜春雨感衷素，蘋藻粢盛严礼仪。","我闻孝诚天所佑，况尔高门先德厚。","传家诗礼喜能存，子子孙孙宜自懋。"]},{"t":"玉树鹡鸰图为姚民泰赋","f":"七言律诗","c":["玉树娟娟雪初霁，琅玕石上苔花碎。","何处飞来双鹡鸰，相顾和鸣有深意。","闻说姚生好弟兄，不学田家分紫荆。","埙篪声里蔼和气，终日披图看鹡鸰。"]},{"t":"子昂兰竹图为莫知观赋","f":"楚辞体","c":["拾翠羽兮湘岸，纫幽佩兮江干。","灵雨滋兮苔石，光风转兮崇兰。","望美人兮延伫，倚修篁兮永叹。","怅王孙兮不返，悼流光兮岁阑。"]},{"t":"山水图为敦生作","f":"七言古诗","c":["滁阳山川素云美，烟树云峦望中起。","雨馀东渡涌波澜，日出丰亭炫青紫。","醒心丰乐久已废，一片寒芜见遗址。","天宁古刹竟何在，紫薇寒泉尚清泚。","我昔承恩来作郡，弹指光阴垂二纪。","琅琊寺里惯题诗，清流关前曾驻履。","况逢时清公事简，俗厚民安称治理。","转官银台又五秋，每忆旧游如梦里。","敦生携我昔作图，复索新吟耀桑梓。","挥毫赋就意无穷，极目滁山馀百里。"]},{"t":"孟尝君墓","f":"七言古诗","c":["薛城城南秋草绿，飒飒悲风撼林木。","荒凉古冢临道隅，踯躅哀歌起樵牧。","忆昔田文当国时，好贤下士思有为。","西行几乎遭虎口，赖有狐裘献幸姬。","东归不复图忠义，一旦忘齐遽归魏。","可怜身死骨未寒，诸子纷争覆宗祀。","当时门下客三千，锦衣珠履犹神仙。","鸡鸣狗盗众誇诩，争似冯生魏子贤。","凄凉旧事逾千载，冢内珍藏竟何在。","我来吊古谩登临，追悼英风发长慨。"]},{"t":"吕梁洪","f":"古风","c":["吕梁天下险，巫峡可并称。","伊昔黄河与清泗，合为一水通郡城。","才出百丈洪，荡潏无时停。","旋涡回洑几十里，古潭渟滀秋泓澄。","两山夹其中，乱石高峥嵘。","不知何年鬼斧凿，中流峎崿无由平。","狂澜泻长谼，奔迸犹建瓴。","珠跳霏霏洒冬雪，震响隐隐疑雷霆。","奔流不可遏，势欲穷沧溟。","乃知此水神莫测，终日常带鱼龙腥。","昨从北京回，扁舟弄清泠。","兹晨偶经此，快我览古情。","举杯酹青山，放歌濯尘缨。","缅思尉迟公，修理费经营。","摩挲赵子碑，感慨岁月更。","矧今天子圣，德化溢八纮。","雨旸喜时若，海岳俱效灵。","龙门三峡已安妥，近岁又报黄河清。","吕梁虽云险，孰怀履险惊。","何当磨崖颂圣德，上与日月同光晶。"]},{"t":"高邮湖闻雁","f":"七言古诗","c":["甓社湖平净如镜，水色天光淡相映。","嗷嗷征雁吐清音，醉倚柁楼闲自听。","听去听来情转恶，大星将沉小星落。","霜风凄凄何处来，吹散馀音满寥廓。","对景令人忆故居，乡园遥在海之隅。","高堂白发应无恙，愿寄平安两字书。"]},{"t":"登歌风台","f":"七言古诗","c":["素灵霄啼大泽前，赤精炎炎光烛天。","阿房已灰四海沸，轵道羊车诚可怜。","谁言汉中非土地，养民致贤真上计。","三秦才定海宇清，税驾咸阳遂称帝。","沛中汤沐新赐名，万乘那忘故里情。","翠华东归喜临幸，父老子弟俱欢迎。","威加海内何雄哉，酒酣更上高高台。","大风歌来真慷慨，守国何独忘贤才。","汉家规模止如此，四百光阴犹撚指。","一旦炎灰不复然，空有荒台临泗水。","我时乘舟台下过，逸兴自觉登临多。","人间兴废等馀事，且将斗酒倾金荷。"]},{"t":"东坡墨竹为郭珍指挥赋","f":"七言古诗","c":["坡翁文艺何尔奇，落笔往往成珠玑。","玉堂昼永风日美，闲写潇湘玉一枝。","贞坚原有冰霜操，潇洒犹含雨露姿。","英娥去后瑶佩冷，碧云深处青鸾飞。","坡翁仙逝不复作，空遗墨迹人宝之。","几回展卷生浩叹，欲赋愧乏琼琚辞。"]},{"t":"龙图为司务淩志赋","f":"七言古诗","c":["伊谁画龙得真趣，眼底霏霏起烟雾。","老龙引子去朝天，欲与虚皇骖玉辂。","冯夷相随辞水府，蜚廉导之浪花舞。","天生神物尔最灵，变化无常孰能伍。","风云际会应有时，好作甘霖遍寰宇。"]},{"t":"所翁龙为员外郎尹祥赋","f":"七言古诗","c":["叶公画龙称绝艺，赫赫声名传后世。","所翁奋起能继之，今睹斯图无乃是。","眼底风云结暝阴，崭然头角出波心。","何当飞跃天池去，四海苍生政望霖。","四灵之中尔其一，变化须臾人莫测。","所翁去后今几年，此日人间见真迹。"]},{"t":"山水图为静轩作","f":"七言古诗","c":["静明山高倚空碧，山下禅林更幽寂。","常闻老衲去参禅，喜见高僧来驻锡。","岚气濛濛路莫分，上方楼阁远嚣尘。","天花时落祇园石，曙色遥连钟阜云。","是中风致由来美，况复写归图画里。","几回丈室谛观时，顿觉心源清似水。"]},{"t":"山水图为霔僧录赋","f":"七言古诗","c":["城南长干古道场，至今舍利腾寒芒。","圣朝敕赐报恩额，梵宇宝塔增辉光。","霔公僧录久驻锡，宗风大振声名彰。","丈室经翻贝叶老，祇园树长昙花香。","有时斋罢坐挥麈，热恼消尽心清凉。","焚芗每喜铜篆古，启户静对钟山苍。","钟山咫尺欣相望，云气缥缈时飞扬。","图中景物宛相似，幽兴满前那可忘。"]},{"t":"山水图为员外沈琮赋","f":"七言古诗","c":["竹鹤轩人画最奇，元晖房山渠所师。","闲将缣素恣挥写，图中墨汁香淋漓。","云收远岫露晴碧，雨过嘉树含华兹。","翠壁水泉寒滴滴，石田瑶草空离离。","几回披玩意自适，如此佳趣唯君知。"]},{"t":"推篷图为顾御史仲谦赋","f":"七言古诗","c":["我昔载酒游西湖，泊舟独爱孤山孤。","山色四围冰玉粲，水光万顷琼瑶铺。","当年梅花喜无恙，倚篷尚见千馀株。","风前暗香还自好，月下瘦影何其疏。","丹书不来仙已逝，白鹤已去谁能呼。","狂吟未就酒初醒，此身如在清冰壶。","我闻顾君复好事，爱梅不让孤山逋。","阿谁能效补之笔，为其写出推篷图。","枯干老梢骨格古，繁葩冷蕊风韵殊。","兹晨示我索题咏，追忆往事空长吁。"]},{"t":"大鹏窝","f":"七言古诗","c":["大山小山千万重，天边削出金芙蓉。","丹崖翠壁宛如画，无乃秀气钟鸿濛。","枪竿龙门俱此通，碧溪流水春溶溶。","犬羊腥秽久荡涤，岩壑往往来清风。","我时扈从随飞龙，竟日笑入烟霞中。","明发浩亹关上去，回瞻秀色郁葱葱。"]},{"t":"扫枯叶","f":"七言律诗","c":["塞草春深犹未茁，沙拥枯根马难齧。","仆夫上山扫叶回，大筐小筐不用切。","料香叶软仅充饥，难比豆秸兼稻秸。","扫叶须扫不落叶，马能添膘少中结。"]},{"t":"宿大王川雷雨大作晓视四山皆雪时四月二十五日也","f":"古风","c":["我家南海头，偶至玄冥北。","南北万馀里，气候孰能测。","车营初到晴川上，暮霭方收日将夕。","维时适当孟夏终，黑云张空如墨色。","大风刮地沙石走，雷雨中宵惊霹雳。","不眠帐下拥貂裘，晓视四山皆雪白。"]},{"t":"紫极宫","f":"五言律诗","c":["琳宇栖真地，喧嚣寂不闻。","鹿眠沾草露，鹤下破松云。","门揭黄金榜，经镌白玉文。","曾言修炼士，来此息尘氛。"]},{"t":"訾家洲宴集偶成柬董伯琪诸先生","f":"五言律诗","c":["訾洲名胜地，雅集萃群英。","绮席临花径，香醪泻玉罂。","菰蒲池上鹭，杨柳水边莺。","何限沧浪兴，临流更濯缨。"]},{"t":"登逍遥楼","f":"五言律诗","c":["幽抱凭谁写，高楼试一登。","天边双鸟白，烟外数峰青。","岁月淹王粲，莼鲈动季鹰。","自惭叨厚禄，无以报朝廷。"]},{"t":"喜晴","f":"五言律诗","c":["三月偏多雨，今朝忽睹晴。","落花千万点，好鸟两三声。","幽草沿阶绿，赪霞入树明。","呼童携酒去，聊作赏春行。"]},{"t":"题典史邵永龄割股手卷","f":"五言律诗","c":["慈母病沉绵，淹淹值暮年。","精神俱已耗，药石苦难痊。","割股时调膳，焚香夜吁天。","此心诚可重，不愧世人传。"]},{"t":"书堂秋意为蒋教谕赋","f":"五言律诗","c":["秋声惊落木，凉气入虚棂。","讲罢风过席，吟馀月在庭。","酒分邻瓮绿，灯照壁书青。","习静多真趣，还期学考亭。"]},{"t":"晚步","f":"五言律诗","c":["缓步出南郊，疏林带夕晖。","鸦归云作阵，鹭聚雪生辉。","桂岭秋来早，漓江叶落稀。","偶逢垂钓者，宴坐澹忘机。"]},{"t":"题江知事耕学卷","f":"五言律诗","c":["学稼勤南亩，传家守一经。","草田春放犊，茅屋夜收萤。","身岂终嘉遁，名期照汗青。","自从鹰鹗荐，归梦绕岩扃。"]}]};